with enrichment(grammar_id,formation_value,usage_value,nuance_value,examples_value) as (
  values
    ('1e24e5d3-4e74-4c17-8516-7b6afa55afef'::uuid,ARRAY['Sinformal というのに']::text[],ARRAY['Use this construction to express A conjunction to indicate that an action/state takes place quite contrary to one''s expectation.. A conjunction to indicate that an action/state takes place quite contrary to one''s expectation.']::text[],ARRAY['【Related Expression: のに】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"四月だというのに、まだ肌寒い。","japanese_furigana":"四月だというのに、まだ肌寒い。","english":"It is April, but still chilly (literally: cold on the skin)."},{"japanese":"明後日はロンドンへ行かなければならないといのに、まだ何も準備していないんですよ。","japanese_furigana":"明後日はロンドンへ行かなければならないといのに、まだ何も準備していないんですよ。","english":"Although I have to go to London the day after tomorrow, I haven''t prepared anything yet, you know."}]'::jsonb),
    ('0b0926d2-54b2-470c-961e-016263bebb2d'::uuid,ARRAY['(i) Noun といえども']::text[],ARRAY['Use this construction to express A conjunction that expresses the idea of “even (though)”.. A conjunction that expresses the idea of “even (though)”.']::text[],ARRAY['【Related Expression: でも】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"医者といえども時に病気になることもある。","japanese_furigana":"医者といえども時に病気になることもある。","english":"Even doctors sometimes become ill. (literally: Even though we call them doctors, there are times when they become ill.)"},{"japanese":"いかなる名人といえども時には失敗することもある。","japanese_furigana":"いかなる名人といえども時には失敗することもある。","english":"Any master sometimes makes a mistake. (literally: No matter what kind of master he/she may be called, he/she sometimes makes a mistake.)"}]'::jsonb),
    ('00514cb9-883e-4804-ad29-9c57756e2180'::uuid,ARRAY['Canonical pattern: どう']::text[],ARRAY['Use this construction to express An interrogative adverb which asks about the state of someone/something or the way of doing something.. An interrogative adverb which asks about the state of someone/something or the way of doing something.']::text[],ARRAY['The core sense is An interrogative adverb which asks about the state of someone/something or the way of doing something.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"お母さんさんはどう（ですか）。","japanese_furigana":"お母さんさんはどう（ですか）。","english":"How''s your mother?"},{"japanese":"新しいアパートはどうですか。","japanese_furigana":"新しいアパートはどうですか。","english":"How''s your new apartment?"}]'::jsonb),
    ('0279ab46-d017-4103-9525-a92ea3d102c6'::uuid,ARRAY['どうか ～ Vて/Vnegativeないで/おVます下さい。']::text[],ARRAY['Use this construction to express An adverb indicating a polite yet very strong request.. An adverb indicating a polite yet very strong request.']::text[],ARRAY['【Related Expression: どうぞ】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"どうか私の言い分を聞いて下さい。","japanese_furigana":"どうか私の言い分を聞いて下さい。","english":"Please listen to what I have to say."},{"japanese":"どうか私を見捨てないで下さい。","japanese_furigana":"どうか私を見捨てないで下さい。","english":"Please don''t abandon me."}]'::jsonb),
    ('3b0e25cf-7942-4703-9b63-3bbe4bcb47ab'::uuid,ARRAY['Canonical pattern: どうせ']::text[],ARRAY['Use this construction to express An adverb that indicates the speaker/writer''s feeling that no matter what s/he does or how s/he does it, the situation will not change.. An adverb that indicates the speaker/writer''s feeling that no matter what s/he does or how s/he does it, the situation will not change.']::text[],ARRAY['The core sense is An adverb that indicates the speaker/writer''s feeling that no matter what s/he does or how s/he does it, the situation will not change.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"受けても、どうせ、駄目だから、文部省の留学生試験を受けないことにしました。","japanese_furigana":"受けても、どうせ、駄目だから、文部省の留学生試験を受けないことにしました。","english":"I decided not to try for the Education Ministry''s Scholarship, because I''d be doomed to failure."},{"japanese":"どうせ外国旅行をするんなら、若いうちにした方がいい。","japanese_furigana":"どうせ外国旅行をするんなら、若いうちにした方がいい。","english":"If you make a trip abroad at all, it''s better to do it when you are young."}]'::jsonb),
    ('aa7ec98c-96b1-4e97-8ef4-932e17a41170'::uuid,ARRAY['Canonical pattern: とうとう']::text[],ARRAY['Use this construction to express An adverb that is used to express the eventual arrival of an expected situation.. An adverb that is used to express the eventual arrival of an expected situation.']::text[],ARRAY['【Related Expression: やっと; ついに】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"朝から降りそうだった雨がとうとう降り出した。","japanese_furigana":"朝から降りそうだった雨がとうとう降り出した。","english":"It''s been threatening to rain since the morning and finally it started to rain. (literally: The rain which threatened to fall from the morning finally started to fall.)"},{"japanese":"弟は医者の忠告を聞かないで煙草を吸い続け、とうとう肺がんになってしまった。","japanese_furigana":"弟は医者の忠告を聞かないで煙草を吸い続け、とうとう肺がんになってしまった。","english":"My younger brother didn''t take his doctor''s advice and kept smoking until he finally got lung cancer."}]'::jsonb),
    ('41d4ed68-b1f9-4daf-884c-fae52ca172aa'::uuid,ARRAY['(i) どうも ~ {V /Adjective (い/な)} negative']::text[],ARRAY['Use this construction to express An adverb to indicate that one cannot make a definite statement about something due to lack of hard evidence.. An adverb to indicate that one cannot make a definite statement about something due to lack of hard evidence.']::text[],ARRAY['The core sense is An adverb to indicate that one cannot make a definite statement about something due to lack of hard evidence.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"この文の意昧がどうもよく分からない。","japanese_furigana":"この文の意昧がどうもよく分からない。","english":"I tried, but I cannot understand the meaning of this Japanese sentence very well."},{"japanese":"鈴木さんはどうも京都大学に入りたいらしい。","japanese_furigana":"鈴木さんはどうも京都大学に入りたいらしい。","english":"I gather that Mr. Suzuki wants to enter Kyoto University."}]'::jsonb),
    ('fdced386-9bc2-46e4-84ea-84a131d0abf2'::uuid,ARRAY['(i) Noun とか Noun とか …']::text[],ARRAY['Use this construction to express A conjunction that lists two or more items, actions or states as inexhaustive examples.. A conjunction that lists two or more items, actions or states as inexhaustive examples.']::text[],ARRAY['【Related Expression: たり; や】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"私はバッハとかモーツアルトとかベートーベンが好きだ・好きです。","japanese_furigana":"私はバッハとかモーツアルトとかベートーベンが好きだ・好きです。","english":"I like Bach, Mozart and Beethoven, among others."},{"japanese":"疲れた時はお風呂に入るとか早く寝るとかしなさい。","japanese_furigana":"疲れた時はお風呂に入るとか早く寝るとかしなさい。","english":"When you are tired, do things like taking a bath or going to sleep early."}]'::jsonb),
    ('5046e4b5-934b-4fb8-b7a8-d99f4c21cc10'::uuid,ARRAY['Sinformal とかで']::text[],ARRAY['Use this construction to express A conjunction that is used to give an uncertain reason for something.. A conjunction that is used to give an uncertain reason for something.']::text[],ARRAY['【Related Expression: から; ので】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"高木さんは大阪に出張するとかでパーティーに来なかった。","japanese_furigana":"高木さんは大阪に出張するとかでパーティーに来なかった。","english":"Mr. Takagi didn''t show up at the party, saying something like he was going to make a business trip to Osaka."},{"japanese":"友人の竹田は大学の授業が面白くないとかで大学を辞めてしまった。","japanese_furigana":"友人の竹田は大学の授業が面白くないとかで大学を辞めてしまった。","english":"My friend Takeda quit college, saying something like the college classes weren''t interesting."}]'::jsonb),
    ('e2ebf9aa-e75b-452f-ace2-e5d1bcd02d0d'::uuid,ARRAY['Vinformal past ところ']::text[],ARRAY['Use this construction to express A dependent noun which is used to express the idea that when someone did something, something took place as the result.. A dependent noun which is used to express the idea that when someone did something, something took place as the result.']::text[],ARRAY['【Related Expression: たら】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"先生に相談したところ、ぜひ大学院に行くよう進められた。","japanese_furigana":"先生に相談したところ、ぜひ大学院に行くよう進められた。","english":"When I consulted with my teacher, he strongly advised me to go to graduate school."},{"japanese":"部長に頼んでみたところ、喜んで引き受けてくれた。","japanese_furigana":"部長に頼んでみたところ、喜んで引き受けてくれた。","english":"When I asked my boss (literally: department chief), he was glad to do it."}]'::jsonb),
    ('c9493819-aaef-4cd5-9b70-4cd7755b244b'::uuid,ARRAY['Canonical pattern: ところが']::text[],ARRAY['Use this construction to express A conjunction which is used to present what in fact happened or what is in fact the case when something else was/is expected.. A conjunction which is used to present what in fact happened or what is in fact the case when something else was/is expected.']::text[],ARRAY['【Related Expression: だが; けれど(も); しかし; それが】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"日本式の部屋に泊まりたいと思って旅館を予約した。ところが、通された部屋は洋式だった。","japanese_furigana":"日本式の部屋に泊まりたいと思って旅館を予約した。ところが、通された部屋は洋式だった。","english":"I wanted to stay in a Japanese-style room and made a reservation at an inn. However, the room I was shown to was a Western-style one."},{"japanese":"Ａ：彼女にプロポーズしたんだろう？どうだった？Ｂ：ところが、駄目だったんだ。","japanese_furigana":"Ａ：彼女にプロポーズしたんだろう？どうだった？Ｂ：ところが、駄目だったんだ。","english":"A: You proposed to her, right? What happened? B: It didn''t work out. (literally: It was no good.)"}]'::jsonb),
    ('204ba5be-470c-4964-a271-8fcd930314af'::uuid,ARRAY['(i) {Vinformal /Adjective い} informal nonpast どころか']::text[],ARRAY['Use this construction to express A conjunction indicating that someone/something is very far from an expected state.. A conjunction indicating that someone/something is very far from an expected state.']::text[],ARRAY['【Related Expression: ばかりか~(さえ)】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"私は日本語が話せるどころか、一度も勉強したことがありません。","japanese_furigana":"私は日本語が話せるどころか、一度も勉強したことがありません。","english":"I am far from being able to speak Japanese. I haven''t studied it at all."},{"japanese":"ジムは日本語の会話が出来ないどころか、簡単なあいさつも出来ない。","japanese_furigana":"ジムは日本語の会話が出来ないどころか、簡単なあいさつも出来ない。","english":"Jim is not just unable to converse in Japanese; he cannot even make simple greetings."}]'::jsonb),
    ('a8ea9fe3-24da-4d24-b949-cbe41e33935d'::uuid,ARRAY['Canonical pattern: ところだ（距離・所要）']::text[],ARRAY['Use this construction to express A place is in a location which takes a certain amount of time to get to.. A place is in a location which takes a certain amount of time to get to.']::text[],ARRAY['The core sense is A place is in a location which takes a certain amount of time to get to.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"私のうちは駅から歩いて十分のところだ・です。","japanese_furigana":"私のうちは駅から歩いて十分のところだ・です。","english":"My house is in a place where it takes ten minutes to get to from the station on foot. / On foot my house is ten minutes from the station."},{"japanese":"学校はうちからバスで三十分のところです。","japanese_furigana":"学校はうちからバスで三十分のところです。","english":"My school is in a place where it takes thirty minutes to get to from home by bus. / By bus it takes thirty minutes to get from home to school."}]'::jsonb),
    ('f2ae3cfa-86dc-439f-818b-92a23a67b7c1'::uuid,ARRAY['(i) Wh-word+Vvol とも']::text[],ARRAY['Use this construction to express A conjunction in written Japanese that is used to express a concession.. A conjunction in written Japanese that is used to express a concession.']::text[],ARRAY['【Related Expression: ても; たって】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"よく勉強したから、試験にどんな問題が出ようとも大丈夫だ。","japanese_furigana":"よく勉強したから、試験にどんな問題が出ようとも大丈夫だ。","english":"Since I studied hard I feel confident no matter what problem shows up on the test."},{"japanese":"いかに家事が忙し{く/かろう}とも母は文句一つ言わなかった。","japanese_furigana":"いかに家事が忙し{く/かろう}とも母は文句一つ言わなかった。","english":"No matter how busy she was with housekeeping, my mother never uttered a single complaint."}]'::jsonb),
    ('5b00371c-7dc0-41db-b88a-2c44a78ec24d'::uuid,ARRAY['Vconditional ども']::text[],ARRAY['Use this construction to express A conjunction that indicates concession based on an actual state or action.. A conjunction that indicates concession based on an actual state or action.']::text[],ARRAY['【Related Expression: とも; ても】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"この二つの文章は言い方は違えども、言おうとしていることは同じだ。","japanese_furigana":"この二つの文章は言い方は違えども、言おうとしていることは同じだ。","english":"Although the way in which these two compositions are written is different, their claims are the same."},{"japanese":"行けども行けども人家が見えてこない。","japanese_furigana":"行けども行けども人家が見えてこない。","english":"No matter how far we go, we still can''t see houses."}]'::jsonb),
    ('a179397c-0798-49e2-bad0-d5e79bfb3df8'::uuid,ARRAY['Canonical pattern: と言えば']::text[],ARRAY['Use this construction to express An expression which presents as the topic of a following discourse a phrase which has just been uttered.. An expression which presents as the topic of a following discourse a phrase which has just been uttered.']::text[],ARRAY['【Related Expression: ったら; って】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"A:この本は田中さんに借りたんです。 B:田中さんと言えばもう病気は治ったのかしら。","japanese_furigana":"A:この本は田中さんに借りたんです。 B:田中さんと言えばもう病気は治ったのかしら。","english":"A: I borrowed this book from Mr. Tanaka. B: Speaking of Mr. Tanaka, I wonder if he''s gotten over his illness yet."},{"japanese":"A:次の日曜日は京都へ行くつもりだ。 B:京都と言えば、春子が京都大学の入学試験に通ったそうだ。","japanese_furigana":"A:次の日曜日は京都へ行くつもりだ。 B:京都と言えば、春子が京都大学の入学試験に通ったそうだ。","english":"A: I''m going to Kyoto next Sunday. B: Speaking of Kyoto, I heard that Haruko passed Kyoto University''s entrance exam."}]'::jsonb),
    ('65a945b4-89e5-4b5f-a057-17d37701fc42'::uuid,ARRAY['Sentence1。 と言って 、Sentence2。']::text[],ARRAY['Use this construction to express A conjunction used at the beginning of a sentence to convey the idea of “however”.. A conjunction used at the beginning of a sentence to convey the idea of “however”.']::text[],ARRAY['【Related Expression: しかし; しかしながら; けれども; かといって; だからといって; そうかといって】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"あと１０００万円あればなんとか欲しい家が買える。と言って、そんな大金を借りられるあてはない。","japanese_furigana":"あと１０００万円あればなんとか欲しい家が買える。と言って、そんな大金を借りられるあてはない。","english":"If we had another ten million yen, we could manage to buy the house we want. Having said that, we don''t know how we could borrow that much money."},{"japanese":"外食は飽きたし自分で料理するのも億劫だ。と言って、何も食べずにいるというわけにもいかない。","japanese_furigana":"外食は飽きたし自分で料理するのも億劫だ。と言って、何も食べずにいるというわけにもいかない。","english":"I''ve gotten tired of eating out, and cooking for myself is tiresome, too. But, I have to eat something (literally: I can''t just not eat)."}]'::jsonb),
    ('641eb9bd-ec41-4952-8de4-3a7bcc672cf0'::uuid,ARRAY['Vinformal nonpast な']::text[],ARRAY['Use this construction to express A negative imperative marker used by a male speaker in very informal speech. A negative imperative marker used by a male speaker in very informal speech']::text[],ARRAY['The core sense is A negative imperative marker used by a male speaker in very informal speech; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"煙草を吸うな！","japanese_furigana":"煙草を吸うな！","english":"Don''t smoke!"},{"japanese":"酒をあまり飲むな！","japanese_furigana":"酒をあまり飲むな！","english":"Don''t drink too much sake!"}]'::jsonb),
    ('708b2b36-7f42-416e-8051-1074942996cf'::uuid,ARRAY['(i) Sinformal']::text[],ARRAY['Use this construction to express An exclamatory sentential particle which is used in informal male speech.. An exclamatory sentential particle which is used in informal male speech.']::text[],ARRAY['The core sense is An exclamatory sentential particle which is used in informal male speech.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"彼はよく食べるなあ。","japanese_furigana":"彼はよく食べるなあ。","english":"He eats a lot!"},{"japanese":"素晴らしい映画だなあと思った。","japanese_furigana":"素晴らしい映画だなあと思った。","english":"I was so impressed by that (wonderful) movie. (literally: What a wonderful movie, I thought.)"}]'::jsonb),
    ('5c9fe359-29b3-4ed7-b4fe-6e88f85b25bd'::uuid,ARRAY['{V/Adjectiveい/な/Copula}negative ないこと { も / は } ない']::text[],ARRAY['Use this construction to express A double negative phrase used to make a conditional affirmative statement.. A double negative phrase used to make a conditional affirmative statement.']::text[],ARRAY['【Related Expression: ことは】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"Ａ：日本語の新聞は読まないんですか。Ｂ：いいえ、読まないこと{も/は}ないんですが、時たまですね。","japanese_furigana":"Ａ：日本語の新聞は読まないんですか。Ｂ：いいえ、読まないこと{も/は}ないんですが、時たまですね。","english":"A: Don''t you read Japanese newspapers? B: I do read them, but very rarely. (literally: It isn''t the case that I don''t read them, but very rarely.)"},{"japanese":"A: この辺は夏涼しくないんですか。B: いや、涼しくないこともないんですが、時々ひどく暑くなります。","japanese_furigana":"A: この辺は夏涼しくないんですか。B: いや、涼しくないこともないんですが、時々ひどく暑くなります。","english":"A: Isn''t it cool around here during the summer? B: Yes, it is cool, but sometimes it gets terribly hot."}]'::jsonb),
    ('65a27500-c647-44ba-b8a2-17b9c9af3c12'::uuid,ARRAY['(i) Vnegative ないまでも']::text[],ARRAY['Use this construction to express An adverbial phrase expressing the speaker’s feeling that although an ideal action or state isn’t possible, at least the next best action or state is or should be available.. An adverbial phrase expressing the speaker’s feeling that although an ideal action or state isn’t possible, at least the next best action or state is or should be available.']::text[],ARRAY['The core sense is An adverbial phrase expressing the speaker’s feeling that although an ideal action or state isn’t possible, at least the next best action or state is or should be available.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"この公演は大成功とは言えないまでも、それなりの成果をもたらした。","japanese_furigana":"この公演は大成功とは言えないまでも、それなりの成果をもたらした。","english":"Although you may not be able to call this public performance a great success, it produced results of a sort."},{"japanese":"彼の論文は決して多くないまでも、その質は非常に高い。","japanese_furigana":"彼の論文は決して多くないまでも、その質は非常に高い。","english":"Although he hasn''t published many papers at all, the quality (of those he has published) is extremely high."}]'::jsonb),
    ('f04b4237-e6a6-4e04-a7e5-0cf29e862f2b'::uuid,ARRAY['(i) なお Vている']::text[],ARRAY['Use this construction to express An adverb that indicates that an action or state is still going on or the degree of something increases; a conjunction indicating that an additional comment follows what has just been said in the preceding sentence.. An adverb that indicates that an action or state is still going on or the degree of something increases; a conjunction indicating that an additional comment follows what has just been said in the preceding sentence.']::text[],ARRAY['【Related Expression: 以前(として); まだ; 一層; もっと; 更に; ただ】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"宮崎駿のアニメは、20年、30年たっても、なお古典アニメとして残っているだろう。","japanese_furigana":"宮崎駿のアニメは、20年、30年たっても、なお古典アニメとして残っているだろう。","english":"Anime by Hayao Miyazaki will still remain even in 20 or 30 years as anime classics."},{"japanese":"この小説はパリを知っている人が読めばなお面白いだろう。","japanese_furigana":"この小説はパリを知っている人が読めばなお面白いだろう。","english":"This novel must be all the more interesting if you know Paris."}]'::jsonb),
    ('a34d8ff1-8ead-4beb-8629-9f86a5e71a21'::uuid,ARRAY['Canonical pattern: なおさら']::text[],ARRAY['Use this construction to express An adverb indicating that the degree of something increases due to an additional circumstance.. An adverb indicating that the degree of something increases due to an additional circumstance.']::text[],ARRAY['【Related Expression: 一層】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"前からタイに行きたいと思っていたが、すでに行ったことのある友人が強く勧めたので、なおさら行きたくなった。","japanese_furigana":"前からタイに行きたいと思っていたが、すでに行ったことのある友人が強く勧めたので、なおさら行きたくなった。","english":"I''ve wanted to go to Thailand for a long time, and then a friend who has been there strongly recommended it, so I feel like going there even more now."},{"japanese":"悪人さえも往生するのなら、まして善人はなおさらだ。","japanese_furigana":"悪人さえも往生するのなら、まして善人はなおさらだ。","english":"If even a bad person can go to heaven, then a good person has an even better chance."}]'::jsonb),
    ('784be253-2ab2-420d-8d6d-421934f26ba7'::uuid,ARRAY['(i) なかなか Adjective(い/な)affirmative']::text[],ARRAY['Use this construction to express An adverb used to indicate the speaker''s feelings that something is impressive or his annoyance at slowness or difficulty in achieving something.. An adverb used to indicate the speaker''s feelings that something is impressive or his annoyance at slowness or difficulty in achieving something.']::text[],ARRAY['【Related Expression: 非常に; かなり; 結構; 大変; とても】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"ブラウンさんは日本語がなかなか上手ですね。","japanese_furigana":"ブラウンさんは日本語がなかなか上手ですね。","english":"{Mr. Brown is / Mr. Brown, you are} remarkably good at Japanese."},{"japanese":"この生け花はなかなか見事に生けてある。","japanese_furigana":"この生け花はなかなか見事に生けてある。","english":"This flower arrangement is done quite nicely."}]'::jsonb),
    ('e10f3006-0588-4499-bb6c-fa256accde99'::uuid,ARRAY['(i) Adjective い stem くなく']::text[],ARRAY['Use this construction to express a continuative form of ない used in written Japanese (to indicate a reason/cause for what follows if ない is attached to Adjective (い/な) and contrast if it is attached to a Noun+Copula).. a continuative form of ない used in written Japanese (to indicate a reason/cause for what follows if ない is attached to Adjective (い/な) and contrast if it is attached to a Noun+Copula).']::text[],ARRAY['【Related Expression: ず】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"日本語の期末試験はあまり難しくなく、ほっとした。","japanese_furigana":"日本語の期末試験はあまり難しくなく、ほっとした。","english":"The Japanese final examination was not very hard, and I felt relieved."},{"japanese":"私の研究対象は現代史ではなく、古代史だ。","japanese_furigana":"私の研究対象は現代史ではなく、古代史だ。","english":"My research area is not modern history, but ancient history."}]'::jsonb),
    ('9c9e24a5-5205-48db-9c50-9285f2bec3d9'::uuid,ARRAY['(i) Vnegative なければならない']::text[],ARRAY['Use this construction to express It won’t do if someone does not take some action or if someone or something is not in some state.. It won’t do if someone does not take some action or if someone or something is not in some state.']::text[],ARRAY['【Related Expression: ないといけない; なければいけない; なくてはいけない; なくてはならない; ねばならない】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"A:今日は働かなくてもいいんですか。 B:いいえ、働かなければなりません。","japanese_furigana":"A:今日は働かなくてもいいんですか。 B:いいえ、働かなければなりません。","english":"A: Don''t you have work today? B: Yes, I have work."},{"japanese":"バスケットバールの選手は大きくなければならない・なりません。","japanese_furigana":"バスケットバールの選手は大きくなければならない・なりません。","english":"Basketball players have to be big."}]'::jsonb),
    ('2b2610a6-81d9-4032-89ff-155e77e71fa3'::uuid,ARRAY['Noun なしでは']::text[],ARRAY['Use this construction to express If something/someone is missing.. If something/someone is missing.']::text[],ARRAY['【Related Expression: が(い)なければ; なしには】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"実力なしでは世の中は渡れない。","japanese_furigana":"実力なしでは世の中は渡れない。","english":"Without real talents one cannot get along in the society."},{"japanese":"あなたなしでは生きていけない。","japanese_furigana":"あなたなしでは生きていけない。","english":"Without you I cannot keep on living."}]'::jsonb),
    ('6ffb06af-996f-4ccf-a133-8310d81b6457'::uuid,ARRAY['(i) {N/VN(すること)} Vます/Vinformal nonpastこと/ なしに']::text[],ARRAY['Use this construction to express An adverbial phrase meaning “without (doing) something”.. An adverbial phrase meaning “without (doing) something”.']::text[],ARRAY['【Related Expression: ないで; ずに】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"料金は予告（すること）なしに変更する場合がございます。","japanese_furigana":"料金は予告（すること）なしに変更する場合がございます。","english":"The fee may (literally: will sometimes) change without prior notice."},{"japanese":"友達が何の連絡もなしにいきなり訪ねてきた。","japanese_furigana":"友達が何の連絡もなしにいきなり訪ねてきた。","english":"My friend suddenly dropped by without contacting me ﬁrst."}]'::jsonb),
    ('735af18a-6e76-4a0c-be6a-2822b3ffb335'::uuid,ARRAY['(i) Noun 1 をNoun 2 と なす']::text[],ARRAY['Use this construction to express A verb that means “to cause something to happen”. A verb that means “to cause something to happen”']::text[],ARRAY['【Related Expression: する; 行う; に/となる】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"災い（を）転じて福となす。","japanese_furigana":"災い（を）転じて福となす。","english":"One can turn misfortune into a blessing. [proverb]"},{"japanese":"比喩に関しては現在多くの研究がなされている。","japanese_furigana":"比喩に関しては現在多くの研究がなされている。","english":"A large amount of research is being done on metaphors now."}]'::jsonb),
    ('b52f7dbf-8a71-4194-b783-f0ac2bfeaa67'::uuid,ARRAY['Canonical pattern: なぜか']::text[],ARRAY['Use this construction to express An adverb indicating that the speaker/writer doesn’t know the cause of/reason for something. An adverb indicating that the speaker/writer doesn’t know the cause of/reason for something']::text[],ARRAY['【Related Expression: そうして(だ)か; どう言うわけ(だ)か】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"このところなぜか体の調子が悪い。","japanese_furigana":"このところなぜか体の調子が悪い。","english":"I don''t know why, but I haven''t felt well lately."},{"japanese":"ヨーロッパやアジアには受け入れられなかったSFが、なぜか日本には根づいた。","japanese_furigana":"ヨーロッパやアジアには受け入れられなかったSFが、なぜか日本には根づいた。","english":"Science ﬁction, which did not catch on in Europe and Asia, took root in Japan for some unknown reason."}]'::jsonb),
    ('04ae43f0-42c8-40fa-8baa-e7e0932e6254'::uuid,ARRAY['Canonical pattern: など']::text[],ARRAY['Use this construction to express A marker that indicates exemplification.. A marker that indicates exemplification.']::text[],ARRAY['【Related Expression: なんか】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"日本の食べ物の中では寿司や天ぷらなどが好きだ・好きです。","japanese_furigana":"日本の食べ物の中では寿司や天ぷらなどが好きだ・好きです。","english":"Among Japanese foods I like things like sushi and tempura."},{"japanese":"A:冬休みはどこに行きましょうか。 B:ハワイなどどうですか。","japanese_furigana":"A:冬休みはどこに行きましょうか。 B:ハワイなどどうですか。","english":"A: Where shall we go during the winter vacation? B: How about Hawaii, for example?"}]'::jsonb),
    ('8d3ee176-c80e-4a75-aadc-89a789295c60'::uuid,ARRAY['(i) なまじ ( っか ) ～Conjunction']::text[],ARRAY['Use this construction to express An adverb indicating that something (including an action/state) has a positive value which hasn’t been reached, causing something negative.. An adverb indicating that something (including an action/state) has a positive value which hasn’t been reached, causing something negative.']::text[],ARRAY['【Related Expression: 中途-半端に/な; へたに】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"僕はなまじ（っか）英語ができるばかりに、会社で重宝がられて困っています。","japanese_furigana":"僕はなまじ（っか）英語ができるばかりに、会社で重宝がられて困っています。","english":"Because I know a little English, the office treasures me, which is causing me problems."},{"japanese":"なまじ（っか）｛の/な｝学問は、ひけらかすと人に軽蔑される。","japanese_furigana":"なまじ（っか）｛の/な｝学問は、ひけらかすと人に軽蔑される。","english":"People disdain those who show off (their scant knowledge) but are uneducated (literally: have inadequate scholarship)."}]'::jsonb),
    ('6ddeccd4-18be-4b9f-bd5a-ee9764a37e4b'::uuid,ARRAY['Vinformal nonpast なり']::text[],ARRAY['Use this construction to express A conjunction meaning “soon after”.. A conjunction meaning “soon after”.']::text[],ARRAY['【Related Expression: や否や】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"妻は私の顔を見るなり泣き出した。","japanese_furigana":"妻は私の顔を見るなり泣き出した。","english":"My wife began to cry the moment she saw me (literally: my face)."},{"japanese":"首相は会議場を出るなり記者団の質問攻めにあった。","japanese_furigana":"首相は会議場を出るなり記者団の質問攻めにあった。","english":"The prime minister was bombarded with questions by a group of reporters soon after he left the conference hall."}]'::jsonb),
    ('04a6ca17-ee69-4e2b-928f-d4e8e5732f12'::uuid,ARRAY['(i) Noun 1 はNoun 2 なりに Where Noun 1 =Noun 2']::text[],ARRAY['Use this construction to express In a way/style that is proper to someone/something.. In a way/style that is proper to someone/something.']::text[],ARRAY['The core sense is In a way/style that is proper to someone/something.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"あの人はあの人なりによく考えているらしい。","japanese_furigana":"あの人はあの人なりによく考えているらしい。","english":"He appears to think hard in his own way."},{"japanese":"動物は動物なりのコミュニケーションが出来る。","japanese_furigana":"動物は動物なりのコミュニケーションが出来る。","english":"Animals are capable of their own communication."}]'::jsonb),
    ('3c86f7b1-25ad-4934-ad32-25f2c42f9cfc'::uuid,ARRAY['(i) Sentence1{が/けれど}、 なるほど Sentence2。']::text[],ARRAY['Use this construction to express An adverb indicating that the speaker/writer afﬁrms the correctness of something he/she has heard/read/observed.. An adverb indicating that the speaker/writer afﬁrms the correctness of something he/she has heard/read/observed.']::text[],ARRAY['【Related Expression: 確かに】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"パリはきれいだと聞いていたが、なるほどその芸術性には舌を巻いた。","japanese_furigana":"パリはきれいだと聞いていたが、なるほどその芸術性には舌を巻いた。","english":"I had heard that Paris was a beautiful city, and (literally: but) indeed I was astounded by its artistry."},{"japanese":"なるほど、日本の官僚はいろいろと批判されているが、戦後の日本の復興は彼らに負うところが多い。","japanese_furigana":"なるほど、日本の官僚はいろいろと批判されているが、戦後の日本の復興は彼らに負うところが多い。","english":"It is true that Japanese bureaucrats are criticized in various ways, but we owe them for much of Japan''s post-war recovery."}]'::jsonb),
    ('db6e5d37-9aea-4e12-8f86-fab1e3d3719b'::uuid,ARRAY['(i) なんて V Where V=verb of communiation']::text[],ARRAY['Use this construction to express A phrase used as the colloquial version of なんと.. A phrase used as the colloquial version of なんと.']::text[],ARRAY['The core sense is A phrase used as the colloquial version of なんと.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"レポートのこと、社長はなんて言っていましたか。","japanese_furigana":"レポートのこと、社長はなんて言っていましたか。","english":"What did the president say about the report?"},{"japanese":"きのう見た映画、なんていう映画だったっけ？","japanese_furigana":"きのう見た映画、なんていう映画だったっけ？","english":"What was the title of the movie we saw yesterday?"}]'::jsonb),
    ('0648abd9-8f7d-47e9-9c7d-bb4775e7b846'::uuid,ARRAY['(i) Sinformal にしても だ after Adjectiveなstem and Noun is omitted']::text[],ARRAY['Use this construction to express A conjunction that represents the idea of “even if someone decides to do something,” or “even if/though someone decides that something is true/the case”.. A conjunction that represents the idea of “even if someone decides to do something,” or “even if/though someone decides that something is true/the case”.']::text[],ARRAY['【Related Expression: としても; にしろ/せよ】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"ピアノを買うにしても、こんな狭いアパートでは置くところがない。","japanese_furigana":"ピアノを買うにしても、こんな狭いアパートでは置くところがない。","english":"Even if we decide to buy a piano, we won''t have a place to put it in such a small apartment."},{"japanese":"美紀の言ったことは大げさだったにしても、すべてがウソというわけではないだろう。","japanese_furigana":"美紀の言ったことは大げさだったにしても、すべてがウソというわけではないだろう。","english":"Even though (we agree that) Miki''s story was exaggerated, probably not all of it was untrue."}]'::jsonb),
    ('23017331-ff8d-40d8-aa2e-ba22f5d0f1da'::uuid,ARRAY['(i) Noun について']::text[],ARRAY['Use this construction to express Concerning something/someone.. Concerning something/someone.']::text[],ARRAY['【Related Expression: に関して; のこと】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"私は日本の政治制度について研究しています。","japanese_furigana":"私は日本の政治制度について研究しています。","english":"I am doing research on the Japanese political system."},{"japanese":"スミスさんは日本へ留学することについて色々私に尋ねた。","japanese_furigana":"スミスさんは日本へ留学することについて色々私に尋ねた。","english":"Mr. Smith asked me various questions about his going to Japan for study."}]'::jsonb),
    ('902ced7d-cdee-4eb5-866e-61da10680a81'::uuid,ARRAY['Vinformal nonpast につけ Where V=verb of cognition']::text[],ARRAY['Use this construction to express A conjunction indicating that each time someone perceives something he/she feels or thinks something associated with it.. A conjunction indicating that each time someone perceives something he/she feels or thinks something associated with it.']::text[],ARRAY['【Related Expression: たびに】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"ナポリで撮った両親の写真を見るにつけ、あの時の楽しかった旅行を思い出す。","japanese_furigana":"ナポリで撮った両親の写真を見るにつけ、あの時の楽しかった旅行を思い出す。","english":"When I see the photo of my parents I took in Naples, I remember what a great time we had on that trip."},{"japanese":"新緑の香りを嗅ぐにつけ、「ああ、春なんだなあ」と思わずのほほんとしてしまいます。","japanese_furigana":"新緑の香りを嗅ぐにつけ、「ああ、春なんだなあ」と思わずのほほんとしてしまいます。","english":"As I smell the scent of fresh green foliage, I tell myself it''s finally spring and feel really relaxed, almost without realizing it."}]'::jsonb),
    ('38f4407a-666d-463b-8741-4a8fa8b7d9c3'::uuid,ARRAY['Noun にとって']::text[],ARRAY['Use this construction to express From the standpoint of; so far as someone (or something) is concerned.. From the standpoint of; so far as someone (or something) is concerned.']::text[],ARRAY['【Related Expression: には】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"これは我々にとって無視出来ない問題だ。","japanese_furigana":"これは我々にとって無視出来ない問題だ。","english":"For us this is a problem which cannot be ignored."},{"japanese":"この大学で教えられることは私にとって極めて名誉なことです。","japanese_furigana":"この大学で教えられることは私にとって極めて名誉なことです。","english":"Being able to teach at this university is a big honour for me."}]'::jsonb),
    ('972663ba-e0c4-44fd-a1f1-b703c2c010ad'::uuid,ARRAY['(i) Vinformal nonpast には']::text[],ARRAY['Use this construction to express A conjunction/compound particle to indicate a purpose for doing something.. A conjunction/compound particle to indicate a purpose for doing something.']::text[],ARRAY['【Related Expression: に; 為に; のに】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"豊かな生活を送るには健康が第一だ。","japanese_furigana":"豊かな生活を送るには健康が第一だ。","english":"In order to lead a rich life, health should be your primary concern."},{"japanese":"ハイヒールはハイキングには不向きだ。","japanese_furigana":"ハイヒールはハイキングには不向きだ。","english":"High-heeled shoes are unsuitable for hiking."}]'::jsonb),
    ('47607472-9f6f-4a23-b9ce-b35521a938a6'::uuid,ARRAY['(i) Noun {Ø/なの/である(の)/だった(の)/であった(の)} にもかかわらず']::text[],ARRAY['Use this construction to express Without any relation to a preceding event/situation.. Without any relation to a preceding event/situation.']::text[],ARRAY['【Related Expression: けれど(も); のに】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"懸命な努力にもかかわらず、健一は大学入試に失敗した。","japanese_furigana":"懸命な努力にもかかわらず、健一は大学入試に失敗した。","english":"In spite of his strenuous efforts, Ken''ichi failed the college entrance examination."},{"japanese":"あの人はよく運動をする（の）にもかかわらず、太っている。","japanese_furigana":"あの人はよく運動をする（の）にもかかわらず、太っている。","english":"He is fat, although he exercises a lot."}]'::jsonb),
    ('c19ed55f-a7a5-4715-8ece-868dd6997b1f'::uuid,ARRAY['(i) Noun に反して']::text[],ARRAY['Use this construction to express Contrary to or in contrast to.. Contrary to or in contrast to.']::text[],ARRAY['【Related Expression: にひきかえ; に対して; と逆に】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"今年の東京国際マラソンは大方の予想に反して無名の選手が優勝した。","japanese_furigana":"今年の東京国際マラソンは大方の予想に反して無名の選手が優勝した。","english":"Contrary to the majority''s expectations, an unknown runner won the Tokyo International Marathon this year."},{"japanese":"我が社はテレビの売れ行きが伸びているのに反してオーディオ製品の売れ行きが下がっている。","japanese_furigana":"我が社はテレビの売れ行きが伸びているのに反してオーディオ製品の売れ行きが下がっている。","english":"In our company, in contrast to the increase in sales of TV sets, the sales in audio products are decreasing."}]'::jsonb),
    ('de25808d-da6c-44d8-9306-81d85963fc4a'::uuid,ARRAY['(i) Noun に基づいて / 基づく']::text[],ARRAY['Use this construction to express With something as a basis.. With something as a basis.']::text[],ARRAY['【Related Expression: をもとに(して)】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"事実に基づいてお話しします。","japanese_furigana":"事実に基づいてお話しします。","english":"I will give you the facts. (literally: I will talk on the basis of facts.)"},{"japanese":"これは五百年前の史料に基づく研究だ。","japanese_furigana":"これは五百年前の史料に基づく研究だ。","english":"This is a study based on historical documents from 500 years ago."}]'::jsonb),
    ('4ffbdb77-7b7c-47c6-b3d0-aa84e3fd63dc'::uuid,ARRAY['(i) Noun に対して']::text[],ARRAY['Use this construction to express Regarding something/someone one opposes, compares, or shows interest in regarding something/someone one opposes, compares or shows interest in.. Regarding something/someone one opposes, compares, or shows interest in regarding something/someone one opposes, compares or shows interest in.']::text[],ARRAY['The core sense is Regarding something/someone one opposes, compares, or shows interest in regarding something/someone one opposes, compares or shows interest in.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"これまで日本は外国に対して閉鎖的な政策を取ってきた。","japanese_furigana":"これまで日本は外国に対して閉鎖的な政策を取ってきた。","english":"Up until now Japan has taken a closed policy toward foreign countries."},{"japanese":"日本の大学は入学するのが難しいのに対して、アメリカの大学は卒業するのが難しい。","japanese_furigana":"日本の大学は入学するのが難しいのに対して、アメリカの大学は卒業するのが難しい。","english":"Japanese colleges are hard to enter; whereas American colleges are hard to graduate from."}]'::jsonb),
    ('10cd8f56-48de-4813-b02b-0ec2fd65aee6'::uuid,ARRAY['(i) Vinformal nonpast に { 従って / 従い }']::text[],ARRAY['Use this construction to express Something spontaneously and gradually occurs in accordance with some change.. Something spontaneously and gradually occurs in accordance with some change.']::text[],ARRAY['【Related Expression: につれて; つれ】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"日本の経済力が強くなるに{従って/従い}、日本語学習者が増えてきた。","japanese_furigana":"日本の経済力が強くなるに{従って/従い}、日本語学習者が増えてきた。","english":"As Japan''s economic power has become stronger, Japanese language learners have increased, accordingly."},{"japanese":"契約に{従って/従い}雇用期間を三年とする。","japanese_furigana":"契約に{従って/従い}雇用期間を三年とする。","english":"In accordance with the contract, your tenure shall be three years."}]'::jsonb),
    ('d1504a37-886f-481d-9b01-ce6f0297b2a3'::uuid,ARRAY['Noun に比べると / 比べて']::text[],ARRAY['Use this construction to express If we compare (it) with/to; comparing (it) with.. If we compare (it) with/to; comparing (it) with.']::text[],ARRAY['The core sense is If we compare (it) with/to; comparing (it) with.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"欧米に比べて日本の住宅事情は極めて貧困だ。","japanese_furigana":"欧米に比べて日本の住宅事情は極めて貧困だ。","english":"Compared to (the situations) in Europe and the U.S., the housing situation in Japan is extremely poor."},{"japanese":"日本に来る前に比べると今は大分日本語でものが言えるようになった。","japanese_furigana":"日本に来る前に比べると今は大分日本語でものが言えるようになった。","english":"I can speak Japanese fairly well now (literally: I have become able to say things in Japanese fairly well) compared to my level before I came to Japan."}]'::jsonb),
    ('74d77ff8-be90-4122-8e47-32782a1c7528'::uuid,ARRAY['(i) Noun に過ぎない']::text[],ARRAY['Use this construction to express Something or someone is nothing more than what is stated in terms of amount, degree, status, significance, etc.. Something or someone is nothing more than what is stated in terms of amount, degree, status, significance, etc.']::text[],ARRAY['【Related Expression: だけだ; ただの】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"これは私の私見に過ぎない。","japanese_furigana":"これは私の私見に過ぎない。","english":"This is nothing more than my personal opinion."},{"japanese":"今期の売り上げの伸びは三パーセントに過ぎない。","japanese_furigana":"今期の売り上げの伸びは三パーセントに過ぎない。","english":"The sales increase this term is as little as three percent."}]'::jsonb),
    ('94d93c5a-7b82-4b90-b202-9fe6f5719a83'::uuid,ARRAY['(i) {Vinformal/Adjective い} informal に違いない']::text[],ARRAY['Use this construction to express The speaker is convinced that there is no mistake on his part in guessing something.. The speaker is convinced that there is no mistake on his part in guessing something.']::text[],ARRAY['【Related Expression: だろう; はず; かもしれない】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"下田さんは今日のことを忘れたに違いない・違いありません。","japanese_furigana":"下田さんは今日のことを忘れたに違いない・違いありません。","english":"Mr. Shimoda must have forgotten today’s plans."},{"japanese":"あの先生の試験は難しいに違いない・違いません。","japanese_furigana":"あの先生の試験は難しいに違いない・違いません。","english":"That teacher''s exams must be hard."}]'::jsonb),
    ('35a9d7a2-0531-4cb8-ae31-151bab2a61d9'::uuid,ARRAY['(i) Noun に関して']::text[],ARRAY['Use this construction to express Related to.. Related to.']::text[],ARRAY['【Related Expression: について; のこと】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"消費税に関して与野党の意見が対立した。","japanese_furigana":"消費税に関して与野党の意見が対立した。","english":"With regard to the sales tax, the opinions of the leading party and the opposition parties conflicted."},{"japanese":"人間の言語習得に関してはまだまだ不明のことが多い。","japanese_furigana":"人間の言語習得に関してはまだまだ不明のことが多い。","english":"Concerning human language acquisition, there are still many unknown things."}]'::jsonb),
    ('dbdae833-0e7c-4512-8bdd-a198bdd7bac4'::uuid,ARRAY['Noun に限らず']::text[],ARRAY['Use this construction to express Not limiting something to ~.. Not limiting something to ~.']::text[],ARRAY['【Related Expression: だけで(は)なく~も】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"見合い結婚は日本に限らずほかの国でも行われている。","japanese_furigana":"見合い結婚は日本に限らずほかの国でも行われている。","english":"Arranged marriage is not limited to Japan; it is practiced in other countries, too."},{"japanese":"音楽はクラシックに限らず何でも聞きます。","japanese_furigana":"音楽はクラシックに限らず何でも聞きます。","english":"Talking about music, I listen to any music, not just classical music."}]'::jsonb),
    ('6c86a074-7b87-46f0-8175-0629bfc142d0'::uuid,ARRAY['Vnegative ぬ (Noun/Auxillary)']::text[],ARRAY['Use this construction to express An archaic auxiliary that indicates negation.. An archaic auxiliary that indicates negation.']::text[],ARRAY['【Related Expression: ない; ず】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"グローバルな時代に自国のことだけを考えるわけにはいかぬ。","japanese_furigana":"グローバルな時代に自国のことだけを考えるわけにはいかぬ。","english":"In the global age we cannot think of our own country alone."},{"japanese":"知らぬことを知らぬと言うには勇気が要る。","japanese_furigana":"知らぬことを知らぬと言うには勇気が要る。","english":"When you don''t know something, it takes courage to admit it."}]'::jsonb),
    ('c8026791-0a83-4e00-89a2-4d2f67686ba8'::uuid,ARRAY['Noun のこと']::text[],ARRAY['Use this construction to express Things of/about.. Things of/about.']::text[],ARRAY['【Related Expression: に関して/関する; について】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"私は明日の講義で日本文化のことを話すつもりだ。","japanese_furigana":"私は明日の講義で日本文化のことを話すつもりだ。","english":"I''m going to talk about Japanese culture in my lecture tomorrow."},{"japanese":"彼女のことはもう忘れた方がいいよ。","japanese_furigana":"彼女のことはもう忘れた方がいいよ。","english":"You''d better forget about her now."}]'::jsonb),
    ('b499034b-8c5b-400f-b5e4-5fdf56f09ea3'::uuid,ARRAY['Noun のことだから']::text[],ARRAY['Use this construction to express Because it is a matter of X with which/whom something is habitually the case.. Because it is a matter of X with which/whom something is habitually the case.']::text[],ARRAY['The core sense is Because it is a matter of X with which/whom something is habitually the case.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"中島のことだから、今日もまた遅れて来るだろう。","japanese_furigana":"中島のことだから、今日もまた遅れて来るだろう。","english":"Because Nakajima is always that way (i.e., comes late), he will probably come late again today. (literally: Because it is a matter of Nakajima (who habitually comes late))."},{"japanese":"傷みやすい豆腐のことだから、冷蔵庫に入れておいた方がいいですよ。","japanese_furigana":"傷みやすい豆腐のことだから、冷蔵庫に入れておいた方がいいですよ。","english":"Because tofu goes bad quickly, you''d better put it in the refrigerator. (literally: Because it is a matter of tofu, which always goes bad quickly . . .)"}]'::jsonb),
    ('b0976b98-eb8e-49ec-a11e-df7b65754c3c'::uuid,ARRAY['(i) {V/Adjective い} informal のだ']::text[],ARRAY['Use this construction to express A sentence ending which indicates that the speaker is explaining or asking for an explanation about some information shared with the hearer, or is talking about something emotively, as if it were of common interest to the speaker and the hearer.. A sentence ending which indicates that the speaker is explaining or asking for an explanation about some information shared with the hearer, or is talking about something emotively, as if it were of common interest to the speaker and the hearer.']::text[],ARRAY['The core sense is A sentence ending which indicates that the speaker is explaining or asking for an explanation about some information shared with the hearer, or is talking about something emotively, as if it were of common interest to the speaker and the hearer.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"何をしているん・のですか。","japanese_furigana":"何をしているん・のですか。","english":"What are you doing?"},{"japanese":"日本語を勉強しているん・のです。","japanese_furigana":"日本語を勉強しているん・のです。","english":"I''m studying Japanese."}]'::jsonb),
    ('4e834db5-eecc-4419-9ac3-4a40dddb1187'::uuid,ARRAY['Noun の上では']::text[],ARRAY['Use this construction to express As far as ~ is concerned.. As far as ~ is concerned.']::text[],ARRAY['【Related Expression: じょうは】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"この計画は書類の上では問題なさそうだ。","japanese_furigana":"この計画は書類の上では問題なさそうだ。","english":"There seems to be no problem with this plan as far as the documents are concerned."},{"japanese":"計算の上では二百万円ぐらい儲かることになっている。","japanese_furigana":"計算の上では二百万円ぐらい儲かることになっている。","english":"According to the calculations, we are supposed to make a profit of (about) two million yen."}]'::jsonb),
    ('a14c3a76-8d25-4297-9d36-4bec989a1204'::uuid,ARRAY['Noun の下で']::text[],ARRAY['Use this construction to express Under some object; under the control or influence of someone or something.. Under some object; under the control or influence of someone or something.']::text[],ARRAY['【Related Expression: かで】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"私は鈴木先生の指導の下で修士論文を書き上げた。","japanese_furigana":"私は鈴木先生の指導の下で修士論文を書き上げた。","english":"I finished my master''s thesis under Professor Suzuki''s guidance."},{"japanese":"さんさんたる太陽の下で開会式が行われた。","japanese_furigana":"さんさんたる太陽の下で開会式が行われた。","english":"The opening ceremony was held in (literally: under) the brilliant sun."}]'::jsonb),
    ('0f4f4545-e19a-4033-b2ce-3ebd4d1376d7'::uuid,ARRAY['Canonical pattern: は〜が']::text[],ARRAY['Use this construction to express A construction which relates a non-controllable state of something or someone to a topic. A construction which relates a non-controllable state of something or someone to a topic']::text[],ARRAY['The core sense is A construction which relates a non-controllable state of something or someone to a topic; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"私は英語が分かる・分かります。","japanese_furigana":"私は英語が分かる・分かります。","english":"To me, English is understandable."},{"japanese":"花子は目が奇麗だ・奇麗です。","japanese_furigana":"花子は目が奇麗だ・奇麗です。","english":"Speaking of Hanako, her eyes are pretty."}]'::jsonb),
    ('852084c3-01b2-43da-b941-ad9a915d6c23'::uuid,ARRAY['Canonical pattern: は〜だ']::text[],ARRAY['Use this construction to express Someone or something is/was someone or something or is/was in some state, or will do/does/did something.. Someone or something is/was someone or something or is/was in some state, or will do/does/did something.']::text[],ARRAY['The core sense is Someone or something is/was someone or something or is/was in some state, or will do/does/did something.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"これは本だ・です。","japanese_furigana":"これは本だ・です。","english":"This is a book."},{"japanese":"コンサートは八時からだ・です。","japanese_furigana":"コンサートは八時からだ・です。","english":"The concert is from eight o''clock."}]'::jsonb),
    ('73ad8ee4-166e-4718-9a37-cdaa6575f399'::uuid,ARRAY['(i) Vinformal past ばかりに']::text[],ARRAY['Use this construction to express A conjunction indicating that a single factor causes a negative situation.. A conjunction indicating that a single factor causes a negative situation.']::text[],ARRAY['The core sense is A conjunction indicating that a single factor causes a negative situation.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"僕が一言変なことを言ったばかりに彼女との関係は悪くなってしまった。","japanese_furigana":"僕が一言変なことを言ったばかりに彼女との関係は悪くなってしまった。","english":"Just because I said one nasty thing to her, my relationship with her deteriorated."},{"japanese":"あの子は、体が弱いばかりにクラスメートにいじめられている。","japanese_furigana":"あの子は、体が弱いばかりにクラスメートにいじめられている。","english":"That child is being bullied by his classmates simply because he is (physically) weak."}]'::jsonb),
    ('769dbdb0-7982-4140-81be-a117f3646f58'::uuid,ARRAY['(i) {v/Adjective い} Conditional ばこそ']::text[],ARRAY['Use this construction to express A conjunction that emphasizes a reason. A conjunction that emphasizes a reason']::text[],ARRAY['【Related Expression: からこそ】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"環境保護を支持していればこそ植林に力を入れているのだ。","japanese_furigana":"環境保護を支持していればこそ植林に力を入れているのだ。","english":"It is only because I support environmental protection so much that I put my efforts into planting trees."},{"japanese":"「愛」があればこそ生きる喜びがある。","japanese_furigana":"「愛」があればこそ生きる喜びがある。","english":"Only because there is love is there joy for living."}]'::jsonb),
    ('e62ad074-7b57-4869-9abe-5b6bb15c6853'::uuid,ARRAY['(i) はたして {V/Adjectiveい}informal past']::text[],ARRAY['Use this construction to express An adverb indicating that something occurred as the writer expected, or expressing in a concession clause the writer’s strong doubt.. An adverb indicating that something occurred as the writer expected, or expressing in a concession clause the writer’s strong doubt.']::text[],ARRAY['【Related Expression: やはり/やっぱり; 案の定】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"今年の冬も暖冬だと言われていたが、はたして暖冬だった。","japanese_furigana":"今年の冬も暖冬だと言われていたが、はたして暖冬だった。","english":"They said this would be a warm winter, and indeed it has been."},{"japanese":"はたして日本の教育は改革される(の)だろうか。","japanese_furigana":"はたして日本の教育は改革される(の)だろうか。","english":"I wonder if Japanese education will really be reformed at all."}]'::jsonb),
    ('5dc27c39-1f6d-4ff8-955d-40282435cb27'::uuid,ARRAY['Noun は言うまでもなく']::text[],ARRAY['Use this construction to express An adverbial phrase that conveys the meaning of ''not to speak of something/someone''.. An adverbial phrase that conveys the meaning of ''not to speak of something/someone''.']::text[],ARRAY['【Related Expression: ばかりで(は)なく~(も); は言うに及ばず; はもちろん】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"大統領の職務は頭脳は言うまでもなく、体力も要求される。","japanese_furigana":"大統領の職務は頭脳は言うまでもなく、体力も要求される。","english":"The duty of the presidency requires physical strength, not to mention brains."},{"japanese":"日本は土地は言うまでもなく、家も非常に高い。","japanese_furigana":"日本は土地は言うまでもなく、家も非常に高い。","english":"In Japan houses are very expensive, not to mention land."}]'::jsonb),
    ('a2107509-c544-448f-aa2e-ed6a77499aaf'::uuid,ARRAY['(i) ~ Vます ひいては Sentence。']::text[],ARRAY['Use this construction to express An adverb indicating that something is perceived to eventually lead to a signiﬁcant result.. An adverb indicating that something is perceived to eventually lead to a signiﬁcant result.']::text[],ARRAY['【Related Expression: 更に(は)】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"イラクへの攻撃はアメリカの孤立を招き、ひいてはイスラム社会全体との戦争に発展していく恐れがある。","japanese_furigana":"イラクへの攻撃はアメリカの孤立を招き、ひいてはイスラム社会全体との戦争に発展していく恐れがある。","english":"There is fear that an attack against Iraq will bring about American isolation, and eventually will lead to a war with Muslim society as a whole."},{"japanese":"彼は同僚にライバル意識、ひいては殺意すら抱いていた。","japanese_furigana":"彼は同僚にライバル意識、ひいては殺意すら抱いていた。","english":"He regarded his colleague as a rival, even to the point of considering murder."}]'::jsonb),
    ('263994a3-4fee-45be-82f7-421f2852f0bf'::uuid,ARRAY['(i) ひとつ Vてみよう。']::text[],ARRAY['Use this construction to express An adverb used when the speaker intends to do something, or asks someone a favour, or makes a suggestion or gives advice to someone.. An adverb used when the speaker intends to do something, or asks someone a favour, or makes a suggestion or gives advice to someone.']::text[],ARRAY['The core sense is An adverb used when the speaker intends to do something, or asks someone a favour, or makes a suggestion or gives advice to someone.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"ひとつ日本の小説の英訳をやってみょう。","japanese_furigana":"ひとつ日本の小説の英訳をやってみょう。","english":"I will try to translate a Japanese novel into English."},{"japanese":"ひとつゴルフでもやったらどうですか。","japanese_furigana":"ひとつゴルフでもやったらどうですか。","english":"How about giving golf a try?"}]'::jsonb),
    ('1ad30c53-54db-422b-9664-1f149ac5c21a'::uuid,ARRAY['Vinformal nonpast べく Exception: する→{す/する}べく']::text[],ARRAY['Use this construction to express The verb modification form of the auxiliary bekida, which is used to indicate a purpose or aim.. The verb modification form of the auxiliary bekida, which is used to indicate a purpose or aim.']::text[],ARRAY['【Related Expression: 為(に)】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"この大学では、二学期制に変えるべく今準備が進められている。","japanese_furigana":"この大学では、二学期制に変えるべく今準備が進められている。","english":"At this university, preparation is under way for changing (the current system) to a semester system."},{"japanese":"K社は人件費を削減すべく大規模なリストラを行う予定だ。","japanese_furigana":"K社は人件費を削減すべく大規模なリストラを行う予定だ。","english":"K Company plans to execute large-scale restructuring in order to reduce personnel expenses."}]'::jsonb),
    ('a9b01de3-effa-4d03-89e1-ff2263794b66'::uuid,ARRAY['(i) Noun のほうが Noun より']::text[],ARRAY['Use this construction to express Comparing two entities, one is in some state or does something more than the other.. Comparing two entities, one is in some state or does something more than the other.']::text[],ARRAY['【Related Expression: より】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"石田さんのほうが私より若い・若いです。","japanese_furigana":"石田さんのほうが私より若い・若いです。","english":"Mr. Ishida is younger than I am."},{"japanese":"私のほうが上田さんよりよく食べる・食べます。","japanese_furigana":"私のほうが上田さんよりよく食べる・食べます。","english":"I eat more than Ms. Ueda does."}]'::jsonb),
    ('8a3a6a86-2ec1-4e14-80c5-0cea148cd1a2'::uuid,ARRAY['Vinformal past ほうがいい']::text[],ARRAY['Use this construction to express It is strongly suggested that someone do something.. It is strongly suggested that someone do something.']::text[],ARRAY['【Related Expression: たらどうですか】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"日本語の本を読んだほうがいい・いいです。","japanese_furigana":"日本語の本を読んだほうがいい・いいです。","english":"You''d better read Japanese books."},{"japanese":"野菜も食べたほうがいいよ。","japanese_furigana":"野菜も食べたほうがいいよ。","english":"You''d better eat vegetables, too."}]'::jsonb),
    ('03c628ac-a595-4bcf-af02-61bffb1af0c2'::uuid,ARRAY['(i) まさか Sとは {思わなかった/考えてもみなかった}']::text[],ARRAY['Use this construction to express An adverb that indicates the speaker''s strong belief that something is not expected to (have) become a reality.. An adverb that indicates the speaker''s strong belief that something is not expected to (have) become a reality.']::text[],ARRAY['【Related Expression: よもや】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"まさか美智子があんな男と結婚するとは思わなかった。","japanese_furigana":"まさか美智子があんな男と結婚するとは思わなかった。","english":"I never dreamed that Michiko would marry that kind of a guy."},{"japanese":"まさかあたしの誕生日を忘れたんじゃないでしょうね。","japanese_furigana":"まさかあたしの誕生日を忘れたんじゃないでしょうね。","english":"Don''t tell me that you forgot my birthday!"}]'::jsonb),
    ('77a2fab9-387a-4b68-870d-59b095b09c47'::uuid,ARRAY['(i) Subordinate Clause、 まして ( や ) Main Clause。']::text[],ARRAY['Use this construction to express An adverb expressing the idea that because one statement is true, the subsequent statement is naturally true.. An adverb expressing the idea that because one statement is true, the subsequent statement is naturally true.']::text[],ARRAY['【Related Expression: どころか; いわんや】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"アパートの家賃を払うのが精一杯なのに、まして（や）家を買うなんて夢物語だ。","japanese_furigana":"アパートの家賃を払うのが精一杯なのに、まして（や）家を買うなんて夢物語だ。","english":"I am just managing to pay the rent for my apartment; how much more of a dream it is to imagine buying my own house!"},{"japanese":"彼女は日本語で講演もできる。まして（や）日常会話など問題ではない。","japanese_furigana":"彼女は日本語で講演もできる。まして（や）日常会話など問題ではない。","english":"She can give a speech in Japanese, to say nothing of (her ability to handle) everyday conversation."}]'::jsonb),
    ('00f87d5f-f746-4e89-9431-d69d92b32574'::uuid,ARRAY['Vます ましょう']::text[],ARRAY['Use this construction to express A verb ending which indicates the first person’s volition or invitation in formal speech.. A verb ending which indicates the first person’s volition or invitation in formal speech.']::text[],ARRAY['【Related Expression: ませんか】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"私が彼に話しましょう。","japanese_furigana":"私が彼に話しましょう。","english":"I will talk to him."},{"japanese":"映画に行きましょう。","japanese_furigana":"映画に行きましょう。","english":"Let''s go to a movie."}]'::jsonb),
    ('8f4dba6e-924a-46fc-81d7-1fb9947b1d07'::uuid,ARRAY['(i) また Verb [repetition]']::text[],ARRAY['Use this construction to express An adverb/conjunction that indicates repetition or addition.. An adverb/conjunction that indicates repetition or addition.']::text[],ARRAY['【Related Expression: あるいは; 且つ】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"来年の春、またお会いします。","japanese_furigana":"来年の春、またお会いします。","english":"I will see you again next spring."},{"japanese":"山田も東京出身だが、林もまた東京出身だ。","japanese_furigana":"山田も東京出身だが、林もまた東京出身だ。","english":"Yamada is from Tokyo, and Hayashi, too, is from Tokyo."}]'::jsonb),
    ('17c9135c-e8a7-4e97-8683-a6c0f94adf9e'::uuid,ARRAY['(i) Noun (か)、 または Noun']::text[],ARRAY['Use this construction to express A conjunction which connects two choices or possibilities expressed by noun phrases or sentences.. A conjunction which connects two choices or possibilities expressed by noun phrases or sentences.']::text[],ARRAY['【Related Expression: か~; か~かどちらか; それとも】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"現金（か）、または小切手でお払い下さい。","japanese_furigana":"現金（か）、または小切手でお払い下さい。","english":"Please pay either in cash or by check."},{"japanese":"Ａ（か）、またはＢのどちらかを選びなさい。","japanese_furigana":"Ａ（か）、またはＢのどちらかを選びなさい。","english":"Select either A or B."}]'::jsonb),
    ('92053bb2-b873-4530-addf-4c7cd78f4cfd'::uuid,ARRAY['Vinformal nonpast までもない']::text[],ARRAY['Use this construction to express There is no point in going as far as to do something.. There is no point in going as far as to do something.']::text[],ARRAY['【Related Expression: 必要はない; ほどのこともない; には及ばない】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"これは簡単な計算だから計算器を使うまでもない。","japanese_furigana":"これは簡単な計算だから計算器を使うまでもない。","english":"This is a simple calculation, so it is not necessary (to bother) to use a calculator."},{"japanese":"言うまでもなくジョージ・ワシントンはアメリカの初代大統領だ。","japanese_furigana":"言うまでもなくジョージ・ワシントンはアメリカの初代大統領だ。","english":"Needless to say, George Washington was the first president of the United States."}]'::jsonb),
    ('d4665971-bb82-46ae-9893-65282cd36cc7'::uuid,ARRAY['(i) Vinformal past まま']::text[],ARRAY['Use this construction to express An already given situation or condition remains unaltered.. An already given situation or condition remains unaltered.']::text[],ARRAY['【Related Expression: ないで; ずに】】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"弟はテレビをつけたまま寝てしまった・しまいました。","japanese_furigana":"弟はテレビをつけたまま寝てしまった・しまいました。","english":"My younger brother went to sleep leaving the TV on."},{"japanese":"弟はテレビをつけたままにしておいた・おきました。","japanese_furigana":"弟はテレビをつけたままにしておいた・おきました。","english":"My younger brother left the TV on."}]'::jsonb),
    ('a4c3d9c4-eb9e-4988-8ed5-0658148e4e64'::uuid,ARRAY['Vて みせる (Group 2)']::text[],ARRAY['Use this construction to express The speaker''s strong determination to achieve something for others to see.. The speaker''s strong determination to achieve something for others to see.']::text[],ARRAY['The core sense is The speaker''s strong determination to achieve something for others to see.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"僕は小説を書いて、芥川賞を取ってみせる。","japanese_furigana":"僕は小説を書いて、芥川賞を取ってみせる。","english":"I will definitely write a novel and get the Akutagawa Prize."},{"japanese":"僕はこの会社の社長になってみせる。","japanese_furigana":"僕はこの会社の社長になってみせる。","english":"I am determined to become the president of this company."}]'::jsonb),
    ('6e03262c-071d-4f22-8c53-d8cbf09a5496'::uuid,ARRAY['Vて みる']::text[],ARRAY['Use this construction to express Do something to see what it’s like or what will happen.. Do something to see what it’s like or what will happen.']::text[],ARRAY['【Related Expression: ようとする】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"私は日本の小説を読んでみる・みます。","japanese_furigana":"私は日本の小説を読んでみる・みます。","english":"I will read Japanese novels (to see what they are like)."},{"japanese":"面白そうなコンサートだったので行ってみました。","japanese_furigana":"面白そうなコンサートだったので行ってみました。","english":"Since it seemed interesting, I went to the concert (to see what it was like)."}]'::jsonb),
    ('0319512e-2caf-4f68-8411-ff61e7e9dba7'::uuid,ARRAY['(i) V1informal nonpastより({は/も}) むしろ V2informal nonpast (方が～)']::text[],ARRAY['Use this construction to express An adverb that indicates one of two things/people/characteristics has been chosen rather than the other to express speaker’s/writer’s desire, preference or judgment.. An adverb that indicates one of two things/people/characteristics has been chosen rather than the other to express speaker’s/writer’s desire, preference or judgment.']::text[],ARRAY['【Related Expression: かえって; どちらかと言うと】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"夏休みはアルバイトをするよりもむしろ海外旅行がしたい。","japanese_furigana":"夏休みはアルバイトをするよりもむしろ海外旅行がしたい。","english":"During summer vacation I would rather travel abroad than work part-time."},{"japanese":"僕は寿司よりむしろ刺身(の方）が好きだ。","japanese_furigana":"僕は寿司よりむしろ刺身(の方）が好きだ。","english":"I prefer sashimi rather than sushi."}]'::jsonb),
    ('35727416-7d3b-4488-9ddc-8f9f7f95fb3e'::uuid,ARRAY['(i) Noun 1 (か)、 もしくは Noun 2']::text[],ARRAY['Use this construction to express A conjunction to disjunctively connect two items or ideas.. A conjunction to disjunctively connect two items or ideas.']::text[],ARRAY['【Related Expression: それとも; あるいは; まただ; か; ないし(は)】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"この申込書は本人（か）、もしくは保証人が記入しなければならない。","japanese_furigana":"この申込書は本人（か）、もしくは保証人が記入しなければならない。","english":"This application has to be filled in by the applicant or by his/her guarantor."},{"japanese":"ワークショップに出席なさりたい方はオンラインで登録するか、もしくは、メールでお申し込みください。","japanese_furigana":"ワークショップに出席なさりたい方はオンラインで登録するか、もしくは、メールでお申し込みください。","english":"If you want to participate in the workshop, please register online or apply by e-mail."}]'::jsonb),
    ('5f2f1549-c262-4ecc-a211-85fa2e6f4847'::uuid,ARRAY['Sentence1。 もっとも Sentence2({が/けれども})。']::text[],ARRAY['Use this construction to express A conjunction used to add a comment indicating that what the speaker/writer has just expressed is not sufﬁcient.. A conjunction used to add a comment indicating that what the speaker/writer has just expressed is not sufﬁcient.']::text[],ARRAY['【Related Expression: しかし; とは言うものの; ただ】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"運動は体にいいと言われている。もっとも、やりすぎると逆効果だ（が）。","japanese_furigana":"運動は体にいいと言われている。もっとも、やりすぎると逆効果だ（が）。","english":"They say that exercise is good for you (literally: your body), but doing too much will bring about the opposite effect."},{"japanese":"あの政治家は保守的だと言われている。もっとも、時々革新的なことを言うこともあるが。","japanese_furigana":"あの政治家は保守的だと言われている。もっとも、時々革新的なことを言うこともあるが。","english":"That politician is said to be conservative, although he sometimes makes innovative statements."}]'::jsonb),
    ('0d93378e-82d9-4b8a-b2d7-96c382801dda'::uuid,ARRAY['(i) Vinformal nonpast ものではない']::text[],ARRAY['Use this construction to express A sentence-ﬁnal phrase indicating that one shouldn’t do something, one could not possibly do something, or one naturally cannot do something.. A sentence-ﬁnal phrase indicating that one shouldn’t do something, one could not possibly do something, or one naturally cannot do something.']::text[],ARRAY['【Related Expression: べきではない; てはいけない; 当然だ; 当たり前だ】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"夜遅く人に電話をかけるものではない。","japanese_furigana":"夜遅く人に電話をかけるものではない。","english":"You shouldn''t call people late at night."},{"japanese":"彼の演奏は聴けたものではない。","japanese_furigana":"彼の演奏は聴けたものではない。","english":"We cannot bear listening to his performance (literally: His performance isn''t something we could possibly listen to)."}]'::jsonb),
    ('47f0483a-66aa-4c0b-98b6-1bdc48433c59'::uuid,ARRAY['Vpotential informal nonpast ものなら']::text[],ARRAY['Use this construction to express A conjunction indicating that the preceding clause presents a hypothetical situation that is unlikely to become a reality.. A conjunction indicating that the preceding clause presents a hypothetical situation that is unlikely to become a reality.']::text[],ARRAY['The core sense is A conjunction indicating that the preceding clause presents a hypothetical situation that is unlikely to become a reality.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"（もし）一戸建ての家が買えるものなら買いたい。","japanese_furigana":"（もし）一戸建ての家が買えるものなら買いたい。","english":"If I could buy a single family house, I would like to."},{"japanese":"一人でやれるものならやってみろ！","japanese_furigana":"一人でやれるものならやってみろ！","english":"If (you think) you can do it by yourself, go ahead and do it!"}]'::jsonb),
    ('8a515e62-ae6f-4a7a-bc0b-49d6d345a6fa'::uuid,ARRAY['(i) {V/Adjectiveい}informal ものの']::text[],ARRAY['Use this construction to express A conjunction that means “although”.. A conjunction that means “although”.']::text[],ARRAY['【Related Expression: が; けれども】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"通訳の仕事を引き受けたものの、うまくやれる自信がない。","japanese_furigana":"通訳の仕事を引き受けたものの、うまくやれる自信がない。","english":"Although I accepted the interpreting job, I''m not conﬁdent that I can do it well."},{"japanese":"一人でいる方が気楽だとは言うものの、やはり話し相手が欲しいと思うこともある。","japanese_furigana":"一人でいる方が気楽だとは言うものの、やはり話し相手が欲しいと思うこともある。","english":"Although I say being alone is easier, sometimes I want someone to talk with."}]'::jsonb),
    ('cb2e65c0-ddbd-4c7b-9b0b-b8c427d711c2'::uuid,ARRAY['(i) Vconditionalば{Adjectiveい/Vpotential}informal ものを']::text[],ARRAY['Use this construction to express A disjunctive coordinate conjunction expressing the meaning of “although” with the speaker’s strong feeling of discontent. A disjunctive coordinate conjunction expressing the meaning of “although” with the speaker’s strong feeling of discontent']::text[],ARRAY['【Related Expression: のに】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"彼は日本語を続けて勉強すればいいものを、1年間やっただけでやめてしまった。","japanese_furigana":"彼は日本語を続けて勉強すればいいものを、1年間やっただけでやめてしまった。","english":"Although he should have continued studying Japanese, he quit after only one year."},{"japanese":"すぐ医者に診てもらったら簡単に治っていたものを、手遅れになってしまった。","japanese_furigana":"すぐ医者に診てもらったら簡単に治っていたものを、手遅れになってしまった。","english":"Had I gone to the doctor right away, I would have gotten better easily, but I acted too late."}]'::jsonb),
    ('04e44d38-47d6-4de8-a64a-e5f90345fb07'::uuid,ARRAY['Canonical pattern: や']::text[],ARRAY['Use this construction to express A coordinate conjunction that is used to list two or more items (nouns or noun phrases) in an inexhaustive fashion.. A coordinate conjunction that is used to list two or more items (nouns or noun phrases) in an inexhaustive fashion.']::text[],ARRAY['【Related Expression: と1; とか】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"山田さんや小川さんが来た・来ました。","japanese_furigana":"山田さんや小川さんが来た・来ました。","english":"Mr. Yamada and Mr. Ogawa (and others) came."},{"japanese":"山本さんやスミスさんがテニスをしている。","japanese_furigana":"山本さんやスミスさんがテニスをしている。","english":"Mr. Yamamoto, Mr. Smith and others are playing tennis."}]'::jsonb),
    ('267f673b-575a-4b34-b1b0-6ebc132f9088'::uuid,ARRAY['(i) やっと Vinformal']::text[],ARRAY['Use this construction to express An adverb to indicate that something desirable has been finally achieved or will be eventually achieved though with great difficulty.. An adverb to indicate that something desirable has been finally achieved or will be eventually achieved though with great difficulty.']::text[],ARRAY['【Related Expression: かろうじて; なんとか; とうとう; ようやく】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"日本史の期末レポートやっと書き終えた。","japanese_furigana":"日本史の期末レポートやっと書き終えた。","english":"I finally finished writing my Japanese history term paper."},{"japanese":"この道は車がやっと一台通れるくらいの狭さです。","japanese_furigana":"この道は車がやっと一台通れるくらいの狭さです。","english":"This street is so narrow that one car can barely go through."}]'::jsonb),
    ('6ab65ca3-a274-4d02-9530-c69a2bd17d2a'::uuid,ARRAY['Canonical pattern: やはり']::text[],ARRAY['Use this construction to express An adverb indicating that the actual situation expectedly/anticipatively conforms to a standard based on past experience, comparison with other people, or common sense.. An adverb indicating that the actual situation expectedly/anticipatively conforms to a standard based on past experience, comparison with other people, or common sense.']::text[],ARRAY['【Related Expression: 結局; さすが(に)】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"ベイリーさんはやはり来なかった・来ませんでしたね。","japanese_furigana":"ベイリーさんはやはり来なかった・来ませんでしたね。","english":"As expected, Mr. Bailey hasn''t come, has he?"},{"japanese":"雪子さんは今でもやはり奇麗です。","japanese_furigana":"雪子さんは今でもやはり奇麗です。","english":"Yukiko is still pretty."}]'::jsonb),
    ('012b2c17-3794-4047-9481-c8b0437b2458'::uuid,ARRAY['(i) Sinformalの やら だ after Adjectiveなstem and Noun changes to な']::text[],ARRAY['Use this construction to express A sentence-ﬁnal particle that marks a self-addressed question.. A sentence-ﬁnal particle that marks a self-addressed question.']::text[],ARRAY['【Related Expression: だろうか; かしら; か】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"このビルが完成するのはいつになるのやら。","japanese_furigana":"このビルが完成するのはいつになるのやら。","english":"I wonder when this building will be ﬁnished."},{"japanese":"これから先、うちの会社は一体どうなることやら。","japanese_furigana":"これから先、うちの会社は一体どうなることやら。","english":"I wonder what will happen to our company from now on. (I''m quite worried.)"}]'::jsonb),
    ('33e5192e-dd91-478e-ab05-5359d4084040'::uuid,ARRAY['(i) someone が someone を place にやる']::text[],ARRAY['Use this construction to express To cause something/someone to move to a place or to do/eat/drink something.. To cause something/someone to move to a place or to do/eat/drink something.']::text[],ARRAY['【Related Expression: する】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"貧乏な家庭は子共を大学にやれない。","japanese_furigana":"貧乏な家庭は子共を大学にやれない。","english":"Poor families cannot send their children to college."},{"japanese":"僕は弟に自転車をやるつもりだ。","japanese_furigana":"僕は弟に自転車をやるつもりだ。","english":"I intend to give a bike to my younger brother."}]'::jsonb),
    ('6a3bf580-5f8f-4510-b8b5-a1ba93c965bf'::uuid,ARRAY['Vinformal nonpast や否や']::text[],ARRAY['Use this construction to express A conjunction that expresses the idea that something happened or someone did something immediately following another event or action.. A conjunction that expresses the idea that something happened or someone did something immediately following another event or action.']::text[],ARRAY['【Related Expression: や; 途端(に); と同時に; とすぐ(に); たらすぐ(に); なり; が早いか; 瞬間に】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"その小説は発売されるや否やミリオンセラーになった。","japanese_furigana":"その小説は発売されるや否やミリオンセラーになった。","english":"The novel sold one million copies as soon as it went on sale."},{"japanese":"彼女は車から降りるや否や報道陣やファンに取り囲まれた。","japanese_furigana":"彼女は車から降りるや否や報道陣やファンに取り囲まれた。","english":"She was surrounded by reporters and fans as soon as she got out of the car."}]'::jsonb),
    ('5daf2e6d-187d-4280-a975-6767816884f0'::uuid,ARRAY['(i) {V/Adjectiveい}informal nonpast ようでは']::text[],ARRAY['Use this construction to express A conjunction that presents an undesirable situation, which is assumed to be factual.. A conjunction that presents an undesirable situation, which is assumed to be factual.']::text[],ARRAY['【Related Expression: ては】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"知らない単語が出てくるたびに辞書を引いているようではいつまでたっても速く読めない。","japanese_furigana":"知らない単語が出てくるたびに辞書を引いているようではいつまでたっても速く読めない。","english":"If (it is true that) you look up unfamiliar words in the dictionary every time you encounter a new one, you will never learn to read fast."},{"japanese":"アパートがそんなに高いようでは私たちは東京には住めない。","japanese_furigana":"アパートがそんなに高いようでは私たちは東京には住めない。","english":"If (it is true that) apartments in Tokyo are that expensive, we cannot live there."}]'::jsonb),
    ('dfeb04ec-66ec-4b6f-8f16-311fa392f605'::uuid,ARRAY['Vinformal nonpast ように言う']::text[],ARRAY['Use this construction to express Tell someone in such a way that he will do something.. Tell someone in such a way that he will do something.']::text[],ARRAY['The core sense is Tell someone in such a way that he will do something.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"先生は学生に宿題をするように言った・言いました。","japanese_furigana":"先生は学生に宿題をするように言った・言いました。","english":"The teacher told his students to do homework."},{"japanese":"坂本さんは雪江に図書館の前で待っているように言いった。","japanese_furigana":"坂本さんは雪江に図書館の前で待っているように言いった。","english":"Mr. Sakamoto told Yukie to be waiting in front of the library."}]'::jsonb),
    ('d32b7721-945d-412e-a36a-9d985f9eb9fb'::uuid,ARRAY['(i) Vnegative んばかりに Exception: する→せんばかりに']::text[],ARRAY['Use this construction to express An adverbial phrase that is used when a situation looks as if someone were about to do something or as if something were about to occur literally or ﬁguratively.. An adverbial phrase that is used when a situation looks as if someone were about to do something or as if something were about to occur literally or ﬁguratively.']::text[],ARRAY['The core sense is An adverbial phrase that is used when a situation looks as if someone were about to do something or as if something were about to occur literally or ﬁguratively.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"犬は噛みつかんばかりに僕に向かってほえた。","japanese_furigana":"犬は噛みつかんばかりに僕に向かってほえた。","english":"The dog barked at me as if it were about to bite."},{"japanese":"どの演奏も若さと情熱あふれんばかりに満ちていた。","japanese_furigana":"どの演奏も若さと情熱あふれんばかりに満ちていた。","english":"Every performance was ﬁlled with an overwhelming amount of youth and passion (literally: as if youth and passion were about to overﬂow)."}]'::jsonb),
    ('ddfc6efa-89e7-4d05-94d4-1de7d259dfca'::uuid,ARRAY['(i) 一つには (もう) 一つには ～']::text[],ARRAY['Use this construction to express An adverb meaning “partly” in a context where someone gives one or two objectives, benefits, examples or reasons for something.. An adverb meaning “partly” in a context where someone gives one or two objectives, benefits, examples or reasons for something.']::text[],ARRAY['The core sense is An adverb meaning “partly” in a context where someone gives one or two objectives, benefits, examples or reasons for something.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"大学教育の目的は、一つには幅広い教養と専門的な知識・能力を授けること、一つには社会に貢献する指導者を育成することだ。","japanese_furigana":"大学教育の目的は、一つには幅広い教養と専門的な知識・能力を授けること、一つには社会に貢献する指導者を育成することだ。","english":"The objective of college education is partly to provide broad schooling and professional knowledge and ability, and partly to train and produce leaders who will contribute to society."},{"japanese":"彼が外国語を好んで勉強しているのは、一つには、異文化学習が好きだからだ。","japanese_furigana":"彼が外国語を好んで勉強しているのは、一つには、異文化学習が好きだからだ。","english":"One reason he likes studying foreign languages is because he likes to learn about different cultures."}]'::jsonb),
    ('0c153a6e-b6e4-48d8-911b-bb3d6ef75fb1'::uuid,ARRAY['Canonical pattern: 一応']::text[],ARRAY['Use this construction to express An adverb indicating that an action or state is only temporary or tentative or is superﬁcially conceived.. An adverb indicating that an action or state is only temporary or tentative or is superﬁcially conceived.']::text[],ARRAY['【Related Expression: とりあえず】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"会議の日取りを一応来週の水曜日と決めておきましょう。","japanese_furigana":"会議の日取りを一応来週の水曜日と決めておきましょう。","english":"Let''s tentatively set our meeting date for next Wednesday."},{"japanese":"私は一応トムにその仕事を担当させることにした。","japanese_furigana":"私は一応トムにその仕事を担当させることにした。","english":"I''ve put Tom in charge of the project for the time being."}]'::jsonb),
    ('53b3aee8-d5e1-4f00-a4d1-97076db656f4'::uuid,ARRAY['(i) {V/Adjectiveい}informal 一方 ( で )']::text[],ARRAY['Use this construction to express A conjunction used to present two concurrent actions/events/states or contrastive situations.. A conjunction used to present two concurrent actions/events/states or contrastive situations.']::text[],ARRAY['【Related Expression: かたわら; 反面】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"我々は化石燃料による環境汚染の問題に対応する一方（で）、新しいエネルギーの開発に力を入れなければならない。","japanese_furigana":"我々は化石燃料による環境汚染の問題に対応する一方（で）、新しいエネルギーの開発に力を入れなければならない。","english":"We have to make more effort in developing new energy (sources) while countering the problem of environmental pollution caused by fossil fuels."},{"japanese":"企業はIT投資には熱心な一方（で）、セキュリティ意識はまだ低いところが多い。","japanese_furigana":"企業はIT投資には熱心な一方（で）、セキュリティ意識はまだ低いところが多い。","english":"Many companies are still not very conscious about (information) security, even though they are eager to invest in information technology."}]'::jsonb),
    ('0d8836af-a17f-4419-bbf1-9da638923333'::uuid,ARRAY['一旦 Verb']::text[],ARRAY['Use this construction to express An adverb meaning “once” or “for a short time”.. An adverb meaning “once” or “for a short time”.']::text[],ARRAY['【Related Expression: 一度】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"このは小説一旦読み始めたらやめられない。","japanese_furigana":"このは小説一旦読み始めたらやめられない。","english":"Once you begin reading this novel, you won''t be able to put it down (literally: stop reading it)."},{"japanese":"邦彦は一旦やめたタバコをまた吸い出した。","japanese_furigana":"邦彦は一旦やめたタバコをまた吸い出した。","english":"Kunihiko resumed smoking, which he had quit for a time."}]'::jsonb),
    ('07d73f12-c35f-460e-8889-f5fc149626be'::uuid,ARRAY['(i) 一番 Adjective い/な']::text[],ARRAY['Use this construction to express A superlative marker.. A superlative marker.']::text[],ARRAY['The core sense is A superlative marker.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"クラス(の中)で大川さんが一番頭がいい。","japanese_furigana":"クラス(の中)で大川さんが一番頭がいい。","english":"Mr. Okawa is the brightest in the class."},{"japanese":"A:この中でどの映画が一番面白いですか。 B:この日本の映画でしょう。","japanese_furigana":"A:この中でどの映画が一番面白いですか。 B:この日本の映画でしょう。","english":"A: Among these, which movie is the most interesting? B: This Japanese movie, I guess."}]'::jsonb),
    ('1c83ad75-e1b5-44b6-967c-380decdd5421'::uuid,ARRAY['Sentence 上 ( に ) The same as relative clause connection rules']::text[],ARRAY['Use this construction to express A conjunction which introduces an additional, emphatic statement.. A conjunction which introduces an additional, emphatic statement.']::text[],ARRAY['【Related Expression: ばかりで(は)なく~も; ばかりか~(さえ); だけで(は)なく~も; その上】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"この映画は話の筋が面白い上（に）配役がいい。","japanese_furigana":"この映画は話の筋が面白い上（に）配役がいい。","english":"Besides the fact that this movie has an interesting storyline, the cast is good."},{"japanese":"彼は仕事を見つけてくれた上（に）お金まで貸してくれた。","japanese_furigana":"彼は仕事を見つけてくれた上（に）お金まで貸してくれた。","english":"Not only did he find me a job, he even lent me some money."}]'::jsonb),
    ('427f8d15-5e5c-4ea6-9e06-d4978135576e'::uuid,ARRAY['(i) {Vます/Vて}、 且つ']::text[],ARRAY['Use this construction to express A conjunction meaning “and” that connects words, phrases and sentences.. A conjunction meaning “and” that connects words, phrases and sentences.']::text[],ARRAY['【Related Expression: と; や; また; その上; 更に; 加えて; そして】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"スミス氏は流暢な日本語を話し、且つ日本の歴史や文化にも明るい。","japanese_furigana":"スミス氏は流暢な日本語を話し、且つ日本の歴史や文化にも明るい。","english":"Mr. Smith is ﬂuent in Japanese and is also knowledgeable about Japanese history and culture."},{"japanese":"この本は、分かりやすく、且つ味わい深い言葉で書かれている。","japanese_furigana":"この本は、分かりやすく、且つ味わい深い言葉で書かれている。","english":"This book is written in language that is easy to understand but also profound."}]'::jsonb)
), invalid as (
  select grammar_id from enrichment where not public.repository_reference_examples_valid(examples_value)
)
select case when count(*)=0 then true else false end as payloads_valid from invalid;

with enrichment(grammar_id,formation_value,usage_value,nuance_value,examples_value) as (
  values
    ('1e24e5d3-4e74-4c17-8516-7b6afa55afef'::uuid,ARRAY['Sinformal というのに']::text[],ARRAY['Use this construction to express A conjunction to indicate that an action/state takes place quite contrary to one''s expectation.. A conjunction to indicate that an action/state takes place quite contrary to one''s expectation.']::text[],ARRAY['【Related Expression: のに】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"四月だというのに、まだ肌寒い。","japanese_furigana":"四月だというのに、まだ肌寒い。","english":"It is April, but still chilly (literally: cold on the skin)."},{"japanese":"明後日はロンドンへ行かなければならないといのに、まだ何も準備していないんですよ。","japanese_furigana":"明後日はロンドンへ行かなければならないといのに、まだ何も準備していないんですよ。","english":"Although I have to go to London the day after tomorrow, I haven''t prepared anything yet, you know."}]'::jsonb),
    ('0b0926d2-54b2-470c-961e-016263bebb2d'::uuid,ARRAY['(i) Noun といえども']::text[],ARRAY['Use this construction to express A conjunction that expresses the idea of “even (though)”.. A conjunction that expresses the idea of “even (though)”.']::text[],ARRAY['【Related Expression: でも】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"医者といえども時に病気になることもある。","japanese_furigana":"医者といえども時に病気になることもある。","english":"Even doctors sometimes become ill. (literally: Even though we call them doctors, there are times when they become ill.)"},{"japanese":"いかなる名人といえども時には失敗することもある。","japanese_furigana":"いかなる名人といえども時には失敗することもある。","english":"Any master sometimes makes a mistake. (literally: No matter what kind of master he/she may be called, he/she sometimes makes a mistake.)"}]'::jsonb),
    ('00514cb9-883e-4804-ad29-9c57756e2180'::uuid,ARRAY['Canonical pattern: どう']::text[],ARRAY['Use this construction to express An interrogative adverb which asks about the state of someone/something or the way of doing something.. An interrogative adverb which asks about the state of someone/something or the way of doing something.']::text[],ARRAY['The core sense is An interrogative adverb which asks about the state of someone/something or the way of doing something.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"お母さんさんはどう（ですか）。","japanese_furigana":"お母さんさんはどう（ですか）。","english":"How''s your mother?"},{"japanese":"新しいアパートはどうですか。","japanese_furigana":"新しいアパートはどうですか。","english":"How''s your new apartment?"}]'::jsonb),
    ('0279ab46-d017-4103-9525-a92ea3d102c6'::uuid,ARRAY['どうか ～ Vて/Vnegativeないで/おVます下さい。']::text[],ARRAY['Use this construction to express An adverb indicating a polite yet very strong request.. An adverb indicating a polite yet very strong request.']::text[],ARRAY['【Related Expression: どうぞ】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"どうか私の言い分を聞いて下さい。","japanese_furigana":"どうか私の言い分を聞いて下さい。","english":"Please listen to what I have to say."},{"japanese":"どうか私を見捨てないで下さい。","japanese_furigana":"どうか私を見捨てないで下さい。","english":"Please don''t abandon me."}]'::jsonb),
    ('3b0e25cf-7942-4703-9b63-3bbe4bcb47ab'::uuid,ARRAY['Canonical pattern: どうせ']::text[],ARRAY['Use this construction to express An adverb that indicates the speaker/writer''s feeling that no matter what s/he does or how s/he does it, the situation will not change.. An adverb that indicates the speaker/writer''s feeling that no matter what s/he does or how s/he does it, the situation will not change.']::text[],ARRAY['The core sense is An adverb that indicates the speaker/writer''s feeling that no matter what s/he does or how s/he does it, the situation will not change.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"受けても、どうせ、駄目だから、文部省の留学生試験を受けないことにしました。","japanese_furigana":"受けても、どうせ、駄目だから、文部省の留学生試験を受けないことにしました。","english":"I decided not to try for the Education Ministry''s Scholarship, because I''d be doomed to failure."},{"japanese":"どうせ外国旅行をするんなら、若いうちにした方がいい。","japanese_furigana":"どうせ外国旅行をするんなら、若いうちにした方がいい。","english":"If you make a trip abroad at all, it''s better to do it when you are young."}]'::jsonb),
    ('aa7ec98c-96b1-4e97-8ef4-932e17a41170'::uuid,ARRAY['Canonical pattern: とうとう']::text[],ARRAY['Use this construction to express An adverb that is used to express the eventual arrival of an expected situation.. An adverb that is used to express the eventual arrival of an expected situation.']::text[],ARRAY['【Related Expression: やっと; ついに】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"朝から降りそうだった雨がとうとう降り出した。","japanese_furigana":"朝から降りそうだった雨がとうとう降り出した。","english":"It''s been threatening to rain since the morning and finally it started to rain. (literally: The rain which threatened to fall from the morning finally started to fall.)"},{"japanese":"弟は医者の忠告を聞かないで煙草を吸い続け、とうとう肺がんになってしまった。","japanese_furigana":"弟は医者の忠告を聞かないで煙草を吸い続け、とうとう肺がんになってしまった。","english":"My younger brother didn''t take his doctor''s advice and kept smoking until he finally got lung cancer."}]'::jsonb),
    ('41d4ed68-b1f9-4daf-884c-fae52ca172aa'::uuid,ARRAY['(i) どうも ~ {V /Adjective (い/な)} negative']::text[],ARRAY['Use this construction to express An adverb to indicate that one cannot make a definite statement about something due to lack of hard evidence.. An adverb to indicate that one cannot make a definite statement about something due to lack of hard evidence.']::text[],ARRAY['The core sense is An adverb to indicate that one cannot make a definite statement about something due to lack of hard evidence.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"この文の意昧がどうもよく分からない。","japanese_furigana":"この文の意昧がどうもよく分からない。","english":"I tried, but I cannot understand the meaning of this Japanese sentence very well."},{"japanese":"鈴木さんはどうも京都大学に入りたいらしい。","japanese_furigana":"鈴木さんはどうも京都大学に入りたいらしい。","english":"I gather that Mr. Suzuki wants to enter Kyoto University."}]'::jsonb),
    ('fdced386-9bc2-46e4-84ea-84a131d0abf2'::uuid,ARRAY['(i) Noun とか Noun とか …']::text[],ARRAY['Use this construction to express A conjunction that lists two or more items, actions or states as inexhaustive examples.. A conjunction that lists two or more items, actions or states as inexhaustive examples.']::text[],ARRAY['【Related Expression: たり; や】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"私はバッハとかモーツアルトとかベートーベンが好きだ・好きです。","japanese_furigana":"私はバッハとかモーツアルトとかベートーベンが好きだ・好きです。","english":"I like Bach, Mozart and Beethoven, among others."},{"japanese":"疲れた時はお風呂に入るとか早く寝るとかしなさい。","japanese_furigana":"疲れた時はお風呂に入るとか早く寝るとかしなさい。","english":"When you are tired, do things like taking a bath or going to sleep early."}]'::jsonb),
    ('5046e4b5-934b-4fb8-b7a8-d99f4c21cc10'::uuid,ARRAY['Sinformal とかで']::text[],ARRAY['Use this construction to express A conjunction that is used to give an uncertain reason for something.. A conjunction that is used to give an uncertain reason for something.']::text[],ARRAY['【Related Expression: から; ので】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"高木さんは大阪に出張するとかでパーティーに来なかった。","japanese_furigana":"高木さんは大阪に出張するとかでパーティーに来なかった。","english":"Mr. Takagi didn''t show up at the party, saying something like he was going to make a business trip to Osaka."},{"japanese":"友人の竹田は大学の授業が面白くないとかで大学を辞めてしまった。","japanese_furigana":"友人の竹田は大学の授業が面白くないとかで大学を辞めてしまった。","english":"My friend Takeda quit college, saying something like the college classes weren''t interesting."}]'::jsonb),
    ('e2ebf9aa-e75b-452f-ace2-e5d1bcd02d0d'::uuid,ARRAY['Vinformal past ところ']::text[],ARRAY['Use this construction to express A dependent noun which is used to express the idea that when someone did something, something took place as the result.. A dependent noun which is used to express the idea that when someone did something, something took place as the result.']::text[],ARRAY['【Related Expression: たら】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"先生に相談したところ、ぜひ大学院に行くよう進められた。","japanese_furigana":"先生に相談したところ、ぜひ大学院に行くよう進められた。","english":"When I consulted with my teacher, he strongly advised me to go to graduate school."},{"japanese":"部長に頼んでみたところ、喜んで引き受けてくれた。","japanese_furigana":"部長に頼んでみたところ、喜んで引き受けてくれた。","english":"When I asked my boss (literally: department chief), he was glad to do it."}]'::jsonb),
    ('c9493819-aaef-4cd5-9b70-4cd7755b244b'::uuid,ARRAY['Canonical pattern: ところが']::text[],ARRAY['Use this construction to express A conjunction which is used to present what in fact happened or what is in fact the case when something else was/is expected.. A conjunction which is used to present what in fact happened or what is in fact the case when something else was/is expected.']::text[],ARRAY['【Related Expression: だが; けれど(も); しかし; それが】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"日本式の部屋に泊まりたいと思って旅館を予約した。ところが、通された部屋は洋式だった。","japanese_furigana":"日本式の部屋に泊まりたいと思って旅館を予約した。ところが、通された部屋は洋式だった。","english":"I wanted to stay in a Japanese-style room and made a reservation at an inn. However, the room I was shown to was a Western-style one."},{"japanese":"Ａ：彼女にプロポーズしたんだろう？どうだった？Ｂ：ところが、駄目だったんだ。","japanese_furigana":"Ａ：彼女にプロポーズしたんだろう？どうだった？Ｂ：ところが、駄目だったんだ。","english":"A: You proposed to her, right? What happened? B: It didn''t work out. (literally: It was no good.)"}]'::jsonb),
    ('204ba5be-470c-4964-a271-8fcd930314af'::uuid,ARRAY['(i) {Vinformal /Adjective い} informal nonpast どころか']::text[],ARRAY['Use this construction to express A conjunction indicating that someone/something is very far from an expected state.. A conjunction indicating that someone/something is very far from an expected state.']::text[],ARRAY['【Related Expression: ばかりか~(さえ)】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"私は日本語が話せるどころか、一度も勉強したことがありません。","japanese_furigana":"私は日本語が話せるどころか、一度も勉強したことがありません。","english":"I am far from being able to speak Japanese. I haven''t studied it at all."},{"japanese":"ジムは日本語の会話が出来ないどころか、簡単なあいさつも出来ない。","japanese_furigana":"ジムは日本語の会話が出来ないどころか、簡単なあいさつも出来ない。","english":"Jim is not just unable to converse in Japanese; he cannot even make simple greetings."}]'::jsonb),
    ('a8ea9fe3-24da-4d24-b949-cbe41e33935d'::uuid,ARRAY['Canonical pattern: ところだ（距離・所要）']::text[],ARRAY['Use this construction to express A place is in a location which takes a certain amount of time to get to.. A place is in a location which takes a certain amount of time to get to.']::text[],ARRAY['The core sense is A place is in a location which takes a certain amount of time to get to.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"私のうちは駅から歩いて十分のところだ・です。","japanese_furigana":"私のうちは駅から歩いて十分のところだ・です。","english":"My house is in a place where it takes ten minutes to get to from the station on foot. / On foot my house is ten minutes from the station."},{"japanese":"学校はうちからバスで三十分のところです。","japanese_furigana":"学校はうちからバスで三十分のところです。","english":"My school is in a place where it takes thirty minutes to get to from home by bus. / By bus it takes thirty minutes to get from home to school."}]'::jsonb),
    ('f2ae3cfa-86dc-439f-818b-92a23a67b7c1'::uuid,ARRAY['(i) Wh-word+Vvol とも']::text[],ARRAY['Use this construction to express A conjunction in written Japanese that is used to express a concession.. A conjunction in written Japanese that is used to express a concession.']::text[],ARRAY['【Related Expression: ても; たって】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"よく勉強したから、試験にどんな問題が出ようとも大丈夫だ。","japanese_furigana":"よく勉強したから、試験にどんな問題が出ようとも大丈夫だ。","english":"Since I studied hard I feel confident no matter what problem shows up on the test."},{"japanese":"いかに家事が忙し{く/かろう}とも母は文句一つ言わなかった。","japanese_furigana":"いかに家事が忙し{く/かろう}とも母は文句一つ言わなかった。","english":"No matter how busy she was with housekeeping, my mother never uttered a single complaint."}]'::jsonb),
    ('5b00371c-7dc0-41db-b88a-2c44a78ec24d'::uuid,ARRAY['Vconditional ども']::text[],ARRAY['Use this construction to express A conjunction that indicates concession based on an actual state or action.. A conjunction that indicates concession based on an actual state or action.']::text[],ARRAY['【Related Expression: とも; ても】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"この二つの文章は言い方は違えども、言おうとしていることは同じだ。","japanese_furigana":"この二つの文章は言い方は違えども、言おうとしていることは同じだ。","english":"Although the way in which these two compositions are written is different, their claims are the same."},{"japanese":"行けども行けども人家が見えてこない。","japanese_furigana":"行けども行けども人家が見えてこない。","english":"No matter how far we go, we still can''t see houses."}]'::jsonb),
    ('a179397c-0798-49e2-bad0-d5e79bfb3df8'::uuid,ARRAY['Canonical pattern: と言えば']::text[],ARRAY['Use this construction to express An expression which presents as the topic of a following discourse a phrase which has just been uttered.. An expression which presents as the topic of a following discourse a phrase which has just been uttered.']::text[],ARRAY['【Related Expression: ったら; って】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"A:この本は田中さんに借りたんです。 B:田中さんと言えばもう病気は治ったのかしら。","japanese_furigana":"A:この本は田中さんに借りたんです。 B:田中さんと言えばもう病気は治ったのかしら。","english":"A: I borrowed this book from Mr. Tanaka. B: Speaking of Mr. Tanaka, I wonder if he''s gotten over his illness yet."},{"japanese":"A:次の日曜日は京都へ行くつもりだ。 B:京都と言えば、春子が京都大学の入学試験に通ったそうだ。","japanese_furigana":"A:次の日曜日は京都へ行くつもりだ。 B:京都と言えば、春子が京都大学の入学試験に通ったそうだ。","english":"A: I''m going to Kyoto next Sunday. B: Speaking of Kyoto, I heard that Haruko passed Kyoto University''s entrance exam."}]'::jsonb),
    ('65a945b4-89e5-4b5f-a057-17d37701fc42'::uuid,ARRAY['Sentence1。 と言って 、Sentence2。']::text[],ARRAY['Use this construction to express A conjunction used at the beginning of a sentence to convey the idea of “however”.. A conjunction used at the beginning of a sentence to convey the idea of “however”.']::text[],ARRAY['【Related Expression: しかし; しかしながら; けれども; かといって; だからといって; そうかといって】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"あと１０００万円あればなんとか欲しい家が買える。と言って、そんな大金を借りられるあてはない。","japanese_furigana":"あと１０００万円あればなんとか欲しい家が買える。と言って、そんな大金を借りられるあてはない。","english":"If we had another ten million yen, we could manage to buy the house we want. Having said that, we don''t know how we could borrow that much money."},{"japanese":"外食は飽きたし自分で料理するのも億劫だ。と言って、何も食べずにいるというわけにもいかない。","japanese_furigana":"外食は飽きたし自分で料理するのも億劫だ。と言って、何も食べずにいるというわけにもいかない。","english":"I''ve gotten tired of eating out, and cooking for myself is tiresome, too. But, I have to eat something (literally: I can''t just not eat)."}]'::jsonb),
    ('641eb9bd-ec41-4952-8de4-3a7bcc672cf0'::uuid,ARRAY['Vinformal nonpast な']::text[],ARRAY['Use this construction to express A negative imperative marker used by a male speaker in very informal speech. A negative imperative marker used by a male speaker in very informal speech']::text[],ARRAY['The core sense is A negative imperative marker used by a male speaker in very informal speech; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"煙草を吸うな！","japanese_furigana":"煙草を吸うな！","english":"Don''t smoke!"},{"japanese":"酒をあまり飲むな！","japanese_furigana":"酒をあまり飲むな！","english":"Don''t drink too much sake!"}]'::jsonb),
    ('708b2b36-7f42-416e-8051-1074942996cf'::uuid,ARRAY['(i) Sinformal']::text[],ARRAY['Use this construction to express An exclamatory sentential particle which is used in informal male speech.. An exclamatory sentential particle which is used in informal male speech.']::text[],ARRAY['The core sense is An exclamatory sentential particle which is used in informal male speech.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"彼はよく食べるなあ。","japanese_furigana":"彼はよく食べるなあ。","english":"He eats a lot!"},{"japanese":"素晴らしい映画だなあと思った。","japanese_furigana":"素晴らしい映画だなあと思った。","english":"I was so impressed by that (wonderful) movie. (literally: What a wonderful movie, I thought.)"}]'::jsonb),
    ('5c9fe359-29b3-4ed7-b4fe-6e88f85b25bd'::uuid,ARRAY['{V/Adjectiveい/な/Copula}negative ないこと { も / は } ない']::text[],ARRAY['Use this construction to express A double negative phrase used to make a conditional affirmative statement.. A double negative phrase used to make a conditional affirmative statement.']::text[],ARRAY['【Related Expression: ことは】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"Ａ：日本語の新聞は読まないんですか。Ｂ：いいえ、読まないこと{も/は}ないんですが、時たまですね。","japanese_furigana":"Ａ：日本語の新聞は読まないんですか。Ｂ：いいえ、読まないこと{も/は}ないんですが、時たまですね。","english":"A: Don''t you read Japanese newspapers? B: I do read them, but very rarely. (literally: It isn''t the case that I don''t read them, but very rarely.)"},{"japanese":"A: この辺は夏涼しくないんですか。B: いや、涼しくないこともないんですが、時々ひどく暑くなります。","japanese_furigana":"A: この辺は夏涼しくないんですか。B: いや、涼しくないこともないんですが、時々ひどく暑くなります。","english":"A: Isn''t it cool around here during the summer? B: Yes, it is cool, but sometimes it gets terribly hot."}]'::jsonb),
    ('65a27500-c647-44ba-b8a2-17b9c9af3c12'::uuid,ARRAY['(i) Vnegative ないまでも']::text[],ARRAY['Use this construction to express An adverbial phrase expressing the speaker’s feeling that although an ideal action or state isn’t possible, at least the next best action or state is or should be available.. An adverbial phrase expressing the speaker’s feeling that although an ideal action or state isn’t possible, at least the next best action or state is or should be available.']::text[],ARRAY['The core sense is An adverbial phrase expressing the speaker’s feeling that although an ideal action or state isn’t possible, at least the next best action or state is or should be available.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"この公演は大成功とは言えないまでも、それなりの成果をもたらした。","japanese_furigana":"この公演は大成功とは言えないまでも、それなりの成果をもたらした。","english":"Although you may not be able to call this public performance a great success, it produced results of a sort."},{"japanese":"彼の論文は決して多くないまでも、その質は非常に高い。","japanese_furigana":"彼の論文は決して多くないまでも、その質は非常に高い。","english":"Although he hasn''t published many papers at all, the quality (of those he has published) is extremely high."}]'::jsonb),
    ('f04b4237-e6a6-4e04-a7e5-0cf29e862f2b'::uuid,ARRAY['(i) なお Vている']::text[],ARRAY['Use this construction to express An adverb that indicates that an action or state is still going on or the degree of something increases; a conjunction indicating that an additional comment follows what has just been said in the preceding sentence.. An adverb that indicates that an action or state is still going on or the degree of something increases; a conjunction indicating that an additional comment follows what has just been said in the preceding sentence.']::text[],ARRAY['【Related Expression: 以前(として); まだ; 一層; もっと; 更に; ただ】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"宮崎駿のアニメは、20年、30年たっても、なお古典アニメとして残っているだろう。","japanese_furigana":"宮崎駿のアニメは、20年、30年たっても、なお古典アニメとして残っているだろう。","english":"Anime by Hayao Miyazaki will still remain even in 20 or 30 years as anime classics."},{"japanese":"この小説はパリを知っている人が読めばなお面白いだろう。","japanese_furigana":"この小説はパリを知っている人が読めばなお面白いだろう。","english":"This novel must be all the more interesting if you know Paris."}]'::jsonb),
    ('a34d8ff1-8ead-4beb-8629-9f86a5e71a21'::uuid,ARRAY['Canonical pattern: なおさら']::text[],ARRAY['Use this construction to express An adverb indicating that the degree of something increases due to an additional circumstance.. An adverb indicating that the degree of something increases due to an additional circumstance.']::text[],ARRAY['【Related Expression: 一層】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"前からタイに行きたいと思っていたが、すでに行ったことのある友人が強く勧めたので、なおさら行きたくなった。","japanese_furigana":"前からタイに行きたいと思っていたが、すでに行ったことのある友人が強く勧めたので、なおさら行きたくなった。","english":"I''ve wanted to go to Thailand for a long time, and then a friend who has been there strongly recommended it, so I feel like going there even more now."},{"japanese":"悪人さえも往生するのなら、まして善人はなおさらだ。","japanese_furigana":"悪人さえも往生するのなら、まして善人はなおさらだ。","english":"If even a bad person can go to heaven, then a good person has an even better chance."}]'::jsonb),
    ('784be253-2ab2-420d-8d6d-421934f26ba7'::uuid,ARRAY['(i) なかなか Adjective(い/な)affirmative']::text[],ARRAY['Use this construction to express An adverb used to indicate the speaker''s feelings that something is impressive or his annoyance at slowness or difficulty in achieving something.. An adverb used to indicate the speaker''s feelings that something is impressive or his annoyance at slowness or difficulty in achieving something.']::text[],ARRAY['【Related Expression: 非常に; かなり; 結構; 大変; とても】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"ブラウンさんは日本語がなかなか上手ですね。","japanese_furigana":"ブラウンさんは日本語がなかなか上手ですね。","english":"{Mr. Brown is / Mr. Brown, you are} remarkably good at Japanese."},{"japanese":"この生け花はなかなか見事に生けてある。","japanese_furigana":"この生け花はなかなか見事に生けてある。","english":"This flower arrangement is done quite nicely."}]'::jsonb),
    ('e10f3006-0588-4499-bb6c-fa256accde99'::uuid,ARRAY['(i) Adjective い stem くなく']::text[],ARRAY['Use this construction to express a continuative form of ない used in written Japanese (to indicate a reason/cause for what follows if ない is attached to Adjective (い/な) and contrast if it is attached to a Noun+Copula).. a continuative form of ない used in written Japanese (to indicate a reason/cause for what follows if ない is attached to Adjective (い/な) and contrast if it is attached to a Noun+Copula).']::text[],ARRAY['【Related Expression: ず】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"日本語の期末試験はあまり難しくなく、ほっとした。","japanese_furigana":"日本語の期末試験はあまり難しくなく、ほっとした。","english":"The Japanese final examination was not very hard, and I felt relieved."},{"japanese":"私の研究対象は現代史ではなく、古代史だ。","japanese_furigana":"私の研究対象は現代史ではなく、古代史だ。","english":"My research area is not modern history, but ancient history."}]'::jsonb),
    ('9c9e24a5-5205-48db-9c50-9285f2bec3d9'::uuid,ARRAY['(i) Vnegative なければならない']::text[],ARRAY['Use this construction to express It won’t do if someone does not take some action or if someone or something is not in some state.. It won’t do if someone does not take some action or if someone or something is not in some state.']::text[],ARRAY['【Related Expression: ないといけない; なければいけない; なくてはいけない; なくてはならない; ねばならない】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"A:今日は働かなくてもいいんですか。 B:いいえ、働かなければなりません。","japanese_furigana":"A:今日は働かなくてもいいんですか。 B:いいえ、働かなければなりません。","english":"A: Don''t you have work today? B: Yes, I have work."},{"japanese":"バスケットバールの選手は大きくなければならない・なりません。","japanese_furigana":"バスケットバールの選手は大きくなければならない・なりません。","english":"Basketball players have to be big."}]'::jsonb),
    ('2b2610a6-81d9-4032-89ff-155e77e71fa3'::uuid,ARRAY['Noun なしでは']::text[],ARRAY['Use this construction to express If something/someone is missing.. If something/someone is missing.']::text[],ARRAY['【Related Expression: が(い)なければ; なしには】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"実力なしでは世の中は渡れない。","japanese_furigana":"実力なしでは世の中は渡れない。","english":"Without real talents one cannot get along in the society."},{"japanese":"あなたなしでは生きていけない。","japanese_furigana":"あなたなしでは生きていけない。","english":"Without you I cannot keep on living."}]'::jsonb),
    ('6ffb06af-996f-4ccf-a133-8310d81b6457'::uuid,ARRAY['(i) {N/VN(すること)} Vます/Vinformal nonpastこと/ なしに']::text[],ARRAY['Use this construction to express An adverbial phrase meaning “without (doing) something”.. An adverbial phrase meaning “without (doing) something”.']::text[],ARRAY['【Related Expression: ないで; ずに】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"料金は予告（すること）なしに変更する場合がございます。","japanese_furigana":"料金は予告（すること）なしに変更する場合がございます。","english":"The fee may (literally: will sometimes) change without prior notice."},{"japanese":"友達が何の連絡もなしにいきなり訪ねてきた。","japanese_furigana":"友達が何の連絡もなしにいきなり訪ねてきた。","english":"My friend suddenly dropped by without contacting me ﬁrst."}]'::jsonb),
    ('735af18a-6e76-4a0c-be6a-2822b3ffb335'::uuid,ARRAY['(i) Noun 1 をNoun 2 と なす']::text[],ARRAY['Use this construction to express A verb that means “to cause something to happen”. A verb that means “to cause something to happen”']::text[],ARRAY['【Related Expression: する; 行う; に/となる】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"災い（を）転じて福となす。","japanese_furigana":"災い（を）転じて福となす。","english":"One can turn misfortune into a blessing. [proverb]"},{"japanese":"比喩に関しては現在多くの研究がなされている。","japanese_furigana":"比喩に関しては現在多くの研究がなされている。","english":"A large amount of research is being done on metaphors now."}]'::jsonb),
    ('b52f7dbf-8a71-4194-b783-f0ac2bfeaa67'::uuid,ARRAY['Canonical pattern: なぜか']::text[],ARRAY['Use this construction to express An adverb indicating that the speaker/writer doesn’t know the cause of/reason for something. An adverb indicating that the speaker/writer doesn’t know the cause of/reason for something']::text[],ARRAY['【Related Expression: そうして(だ)か; どう言うわけ(だ)か】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"このところなぜか体の調子が悪い。","japanese_furigana":"このところなぜか体の調子が悪い。","english":"I don''t know why, but I haven''t felt well lately."},{"japanese":"ヨーロッパやアジアには受け入れられなかったSFが、なぜか日本には根づいた。","japanese_furigana":"ヨーロッパやアジアには受け入れられなかったSFが、なぜか日本には根づいた。","english":"Science ﬁction, which did not catch on in Europe and Asia, took root in Japan for some unknown reason."}]'::jsonb),
    ('04ae43f0-42c8-40fa-8baa-e7e0932e6254'::uuid,ARRAY['Canonical pattern: など']::text[],ARRAY['Use this construction to express A marker that indicates exemplification.. A marker that indicates exemplification.']::text[],ARRAY['【Related Expression: なんか】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"日本の食べ物の中では寿司や天ぷらなどが好きだ・好きです。","japanese_furigana":"日本の食べ物の中では寿司や天ぷらなどが好きだ・好きです。","english":"Among Japanese foods I like things like sushi and tempura."},{"japanese":"A:冬休みはどこに行きましょうか。 B:ハワイなどどうですか。","japanese_furigana":"A:冬休みはどこに行きましょうか。 B:ハワイなどどうですか。","english":"A: Where shall we go during the winter vacation? B: How about Hawaii, for example?"}]'::jsonb),
    ('8d3ee176-c80e-4a75-aadc-89a789295c60'::uuid,ARRAY['(i) なまじ ( っか ) ～Conjunction']::text[],ARRAY['Use this construction to express An adverb indicating that something (including an action/state) has a positive value which hasn’t been reached, causing something negative.. An adverb indicating that something (including an action/state) has a positive value which hasn’t been reached, causing something negative.']::text[],ARRAY['【Related Expression: 中途-半端に/な; へたに】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"僕はなまじ（っか）英語ができるばかりに、会社で重宝がられて困っています。","japanese_furigana":"僕はなまじ（っか）英語ができるばかりに、会社で重宝がられて困っています。","english":"Because I know a little English, the office treasures me, which is causing me problems."},{"japanese":"なまじ（っか）｛の/な｝学問は、ひけらかすと人に軽蔑される。","japanese_furigana":"なまじ（っか）｛の/な｝学問は、ひけらかすと人に軽蔑される。","english":"People disdain those who show off (their scant knowledge) but are uneducated (literally: have inadequate scholarship)."}]'::jsonb),
    ('6ddeccd4-18be-4b9f-bd5a-ee9764a37e4b'::uuid,ARRAY['Vinformal nonpast なり']::text[],ARRAY['Use this construction to express A conjunction meaning “soon after”.. A conjunction meaning “soon after”.']::text[],ARRAY['【Related Expression: や否や】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"妻は私の顔を見るなり泣き出した。","japanese_furigana":"妻は私の顔を見るなり泣き出した。","english":"My wife began to cry the moment she saw me (literally: my face)."},{"japanese":"首相は会議場を出るなり記者団の質問攻めにあった。","japanese_furigana":"首相は会議場を出るなり記者団の質問攻めにあった。","english":"The prime minister was bombarded with questions by a group of reporters soon after he left the conference hall."}]'::jsonb),
    ('04a6ca17-ee69-4e2b-928f-d4e8e5732f12'::uuid,ARRAY['(i) Noun 1 はNoun 2 なりに Where Noun 1 =Noun 2']::text[],ARRAY['Use this construction to express In a way/style that is proper to someone/something.. In a way/style that is proper to someone/something.']::text[],ARRAY['The core sense is In a way/style that is proper to someone/something.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"あの人はあの人なりによく考えているらしい。","japanese_furigana":"あの人はあの人なりによく考えているらしい。","english":"He appears to think hard in his own way."},{"japanese":"動物は動物なりのコミュニケーションが出来る。","japanese_furigana":"動物は動物なりのコミュニケーションが出来る。","english":"Animals are capable of their own communication."}]'::jsonb),
    ('3c86f7b1-25ad-4934-ad32-25f2c42f9cfc'::uuid,ARRAY['(i) Sentence1{が/けれど}、 なるほど Sentence2。']::text[],ARRAY['Use this construction to express An adverb indicating that the speaker/writer afﬁrms the correctness of something he/she has heard/read/observed.. An adverb indicating that the speaker/writer afﬁrms the correctness of something he/she has heard/read/observed.']::text[],ARRAY['【Related Expression: 確かに】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"パリはきれいだと聞いていたが、なるほどその芸術性には舌を巻いた。","japanese_furigana":"パリはきれいだと聞いていたが、なるほどその芸術性には舌を巻いた。","english":"I had heard that Paris was a beautiful city, and (literally: but) indeed I was astounded by its artistry."},{"japanese":"なるほど、日本の官僚はいろいろと批判されているが、戦後の日本の復興は彼らに負うところが多い。","japanese_furigana":"なるほど、日本の官僚はいろいろと批判されているが、戦後の日本の復興は彼らに負うところが多い。","english":"It is true that Japanese bureaucrats are criticized in various ways, but we owe them for much of Japan''s post-war recovery."}]'::jsonb),
    ('db6e5d37-9aea-4e12-8f86-fab1e3d3719b'::uuid,ARRAY['(i) なんて V Where V=verb of communiation']::text[],ARRAY['Use this construction to express A phrase used as the colloquial version of なんと.. A phrase used as the colloquial version of なんと.']::text[],ARRAY['The core sense is A phrase used as the colloquial version of なんと.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"レポートのこと、社長はなんて言っていましたか。","japanese_furigana":"レポートのこと、社長はなんて言っていましたか。","english":"What did the president say about the report?"},{"japanese":"きのう見た映画、なんていう映画だったっけ？","japanese_furigana":"きのう見た映画、なんていう映画だったっけ？","english":"What was the title of the movie we saw yesterday?"}]'::jsonb),
    ('0648abd9-8f7d-47e9-9c7d-bb4775e7b846'::uuid,ARRAY['(i) Sinformal にしても だ after Adjectiveなstem and Noun is omitted']::text[],ARRAY['Use this construction to express A conjunction that represents the idea of “even if someone decides to do something,” or “even if/though someone decides that something is true/the case”.. A conjunction that represents the idea of “even if someone decides to do something,” or “even if/though someone decides that something is true/the case”.']::text[],ARRAY['【Related Expression: としても; にしろ/せよ】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"ピアノを買うにしても、こんな狭いアパートでは置くところがない。","japanese_furigana":"ピアノを買うにしても、こんな狭いアパートでは置くところがない。","english":"Even if we decide to buy a piano, we won''t have a place to put it in such a small apartment."},{"japanese":"美紀の言ったことは大げさだったにしても、すべてがウソというわけではないだろう。","japanese_furigana":"美紀の言ったことは大げさだったにしても、すべてがウソというわけではないだろう。","english":"Even though (we agree that) Miki''s story was exaggerated, probably not all of it was untrue."}]'::jsonb),
    ('23017331-ff8d-40d8-aa2e-ba22f5d0f1da'::uuid,ARRAY['(i) Noun について']::text[],ARRAY['Use this construction to express Concerning something/someone.. Concerning something/someone.']::text[],ARRAY['【Related Expression: に関して; のこと】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"私は日本の政治制度について研究しています。","japanese_furigana":"私は日本の政治制度について研究しています。","english":"I am doing research on the Japanese political system."},{"japanese":"スミスさんは日本へ留学することについて色々私に尋ねた。","japanese_furigana":"スミスさんは日本へ留学することについて色々私に尋ねた。","english":"Mr. Smith asked me various questions about his going to Japan for study."}]'::jsonb),
    ('902ced7d-cdee-4eb5-866e-61da10680a81'::uuid,ARRAY['Vinformal nonpast につけ Where V=verb of cognition']::text[],ARRAY['Use this construction to express A conjunction indicating that each time someone perceives something he/she feels or thinks something associated with it.. A conjunction indicating that each time someone perceives something he/she feels or thinks something associated with it.']::text[],ARRAY['【Related Expression: たびに】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"ナポリで撮った両親の写真を見るにつけ、あの時の楽しかった旅行を思い出す。","japanese_furigana":"ナポリで撮った両親の写真を見るにつけ、あの時の楽しかった旅行を思い出す。","english":"When I see the photo of my parents I took in Naples, I remember what a great time we had on that trip."},{"japanese":"新緑の香りを嗅ぐにつけ、「ああ、春なんだなあ」と思わずのほほんとしてしまいます。","japanese_furigana":"新緑の香りを嗅ぐにつけ、「ああ、春なんだなあ」と思わずのほほんとしてしまいます。","english":"As I smell the scent of fresh green foliage, I tell myself it''s finally spring and feel really relaxed, almost without realizing it."}]'::jsonb),
    ('38f4407a-666d-463b-8741-4a8fa8b7d9c3'::uuid,ARRAY['Noun にとって']::text[],ARRAY['Use this construction to express From the standpoint of; so far as someone (or something) is concerned.. From the standpoint of; so far as someone (or something) is concerned.']::text[],ARRAY['【Related Expression: には】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"これは我々にとって無視出来ない問題だ。","japanese_furigana":"これは我々にとって無視出来ない問題だ。","english":"For us this is a problem which cannot be ignored."},{"japanese":"この大学で教えられることは私にとって極めて名誉なことです。","japanese_furigana":"この大学で教えられることは私にとって極めて名誉なことです。","english":"Being able to teach at this university is a big honour for me."}]'::jsonb),
    ('972663ba-e0c4-44fd-a1f1-b703c2c010ad'::uuid,ARRAY['(i) Vinformal nonpast には']::text[],ARRAY['Use this construction to express A conjunction/compound particle to indicate a purpose for doing something.. A conjunction/compound particle to indicate a purpose for doing something.']::text[],ARRAY['【Related Expression: に; 為に; のに】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"豊かな生活を送るには健康が第一だ。","japanese_furigana":"豊かな生活を送るには健康が第一だ。","english":"In order to lead a rich life, health should be your primary concern."},{"japanese":"ハイヒールはハイキングには不向きだ。","japanese_furigana":"ハイヒールはハイキングには不向きだ。","english":"High-heeled shoes are unsuitable for hiking."}]'::jsonb),
    ('47607472-9f6f-4a23-b9ce-b35521a938a6'::uuid,ARRAY['(i) Noun {Ø/なの/である(の)/だった(の)/であった(の)} にもかかわらず']::text[],ARRAY['Use this construction to express Without any relation to a preceding event/situation.. Without any relation to a preceding event/situation.']::text[],ARRAY['【Related Expression: けれど(も); のに】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"懸命な努力にもかかわらず、健一は大学入試に失敗した。","japanese_furigana":"懸命な努力にもかかわらず、健一は大学入試に失敗した。","english":"In spite of his strenuous efforts, Ken''ichi failed the college entrance examination."},{"japanese":"あの人はよく運動をする（の）にもかかわらず、太っている。","japanese_furigana":"あの人はよく運動をする（の）にもかかわらず、太っている。","english":"He is fat, although he exercises a lot."}]'::jsonb),
    ('c19ed55f-a7a5-4715-8ece-868dd6997b1f'::uuid,ARRAY['(i) Noun に反して']::text[],ARRAY['Use this construction to express Contrary to or in contrast to.. Contrary to or in contrast to.']::text[],ARRAY['【Related Expression: にひきかえ; に対して; と逆に】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"今年の東京国際マラソンは大方の予想に反して無名の選手が優勝した。","japanese_furigana":"今年の東京国際マラソンは大方の予想に反して無名の選手が優勝した。","english":"Contrary to the majority''s expectations, an unknown runner won the Tokyo International Marathon this year."},{"japanese":"我が社はテレビの売れ行きが伸びているのに反してオーディオ製品の売れ行きが下がっている。","japanese_furigana":"我が社はテレビの売れ行きが伸びているのに反してオーディオ製品の売れ行きが下がっている。","english":"In our company, in contrast to the increase in sales of TV sets, the sales in audio products are decreasing."}]'::jsonb),
    ('de25808d-da6c-44d8-9306-81d85963fc4a'::uuid,ARRAY['(i) Noun に基づいて / 基づく']::text[],ARRAY['Use this construction to express With something as a basis.. With something as a basis.']::text[],ARRAY['【Related Expression: をもとに(して)】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"事実に基づいてお話しします。","japanese_furigana":"事実に基づいてお話しします。","english":"I will give you the facts. (literally: I will talk on the basis of facts.)"},{"japanese":"これは五百年前の史料に基づく研究だ。","japanese_furigana":"これは五百年前の史料に基づく研究だ。","english":"This is a study based on historical documents from 500 years ago."}]'::jsonb),
    ('4ffbdb77-7b7c-47c6-b3d0-aa84e3fd63dc'::uuid,ARRAY['(i) Noun に対して']::text[],ARRAY['Use this construction to express Regarding something/someone one opposes, compares, or shows interest in regarding something/someone one opposes, compares or shows interest in.. Regarding something/someone one opposes, compares, or shows interest in regarding something/someone one opposes, compares or shows interest in.']::text[],ARRAY['The core sense is Regarding something/someone one opposes, compares, or shows interest in regarding something/someone one opposes, compares or shows interest in.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"これまで日本は外国に対して閉鎖的な政策を取ってきた。","japanese_furigana":"これまで日本は外国に対して閉鎖的な政策を取ってきた。","english":"Up until now Japan has taken a closed policy toward foreign countries."},{"japanese":"日本の大学は入学するのが難しいのに対して、アメリカの大学は卒業するのが難しい。","japanese_furigana":"日本の大学は入学するのが難しいのに対して、アメリカの大学は卒業するのが難しい。","english":"Japanese colleges are hard to enter; whereas American colleges are hard to graduate from."}]'::jsonb),
    ('10cd8f56-48de-4813-b02b-0ec2fd65aee6'::uuid,ARRAY['(i) Vinformal nonpast に { 従って / 従い }']::text[],ARRAY['Use this construction to express Something spontaneously and gradually occurs in accordance with some change.. Something spontaneously and gradually occurs in accordance with some change.']::text[],ARRAY['【Related Expression: につれて; つれ】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"日本の経済力が強くなるに{従って/従い}、日本語学習者が増えてきた。","japanese_furigana":"日本の経済力が強くなるに{従って/従い}、日本語学習者が増えてきた。","english":"As Japan''s economic power has become stronger, Japanese language learners have increased, accordingly."},{"japanese":"契約に{従って/従い}雇用期間を三年とする。","japanese_furigana":"契約に{従って/従い}雇用期間を三年とする。","english":"In accordance with the contract, your tenure shall be three years."}]'::jsonb),
    ('d1504a37-886f-481d-9b01-ce6f0297b2a3'::uuid,ARRAY['Noun に比べると / 比べて']::text[],ARRAY['Use this construction to express If we compare (it) with/to; comparing (it) with.. If we compare (it) with/to; comparing (it) with.']::text[],ARRAY['The core sense is If we compare (it) with/to; comparing (it) with.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"欧米に比べて日本の住宅事情は極めて貧困だ。","japanese_furigana":"欧米に比べて日本の住宅事情は極めて貧困だ。","english":"Compared to (the situations) in Europe and the U.S., the housing situation in Japan is extremely poor."},{"japanese":"日本に来る前に比べると今は大分日本語でものが言えるようになった。","japanese_furigana":"日本に来る前に比べると今は大分日本語でものが言えるようになった。","english":"I can speak Japanese fairly well now (literally: I have become able to say things in Japanese fairly well) compared to my level before I came to Japan."}]'::jsonb),
    ('74d77ff8-be90-4122-8e47-32782a1c7528'::uuid,ARRAY['(i) Noun に過ぎない']::text[],ARRAY['Use this construction to express Something or someone is nothing more than what is stated in terms of amount, degree, status, significance, etc.. Something or someone is nothing more than what is stated in terms of amount, degree, status, significance, etc.']::text[],ARRAY['【Related Expression: だけだ; ただの】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"これは私の私見に過ぎない。","japanese_furigana":"これは私の私見に過ぎない。","english":"This is nothing more than my personal opinion."},{"japanese":"今期の売り上げの伸びは三パーセントに過ぎない。","japanese_furigana":"今期の売り上げの伸びは三パーセントに過ぎない。","english":"The sales increase this term is as little as three percent."}]'::jsonb),
    ('94d93c5a-7b82-4b90-b202-9fe6f5719a83'::uuid,ARRAY['(i) {Vinformal/Adjective い} informal に違いない']::text[],ARRAY['Use this construction to express The speaker is convinced that there is no mistake on his part in guessing something.. The speaker is convinced that there is no mistake on his part in guessing something.']::text[],ARRAY['【Related Expression: だろう; はず; かもしれない】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"下田さんは今日のことを忘れたに違いない・違いありません。","japanese_furigana":"下田さんは今日のことを忘れたに違いない・違いありません。","english":"Mr. Shimoda must have forgotten today’s plans."},{"japanese":"あの先生の試験は難しいに違いない・違いません。","japanese_furigana":"あの先生の試験は難しいに違いない・違いません。","english":"That teacher''s exams must be hard."}]'::jsonb),
    ('35a9d7a2-0531-4cb8-ae31-151bab2a61d9'::uuid,ARRAY['(i) Noun に関して']::text[],ARRAY['Use this construction to express Related to.. Related to.']::text[],ARRAY['【Related Expression: について; のこと】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"消費税に関して与野党の意見が対立した。","japanese_furigana":"消費税に関して与野党の意見が対立した。","english":"With regard to the sales tax, the opinions of the leading party and the opposition parties conflicted."},{"japanese":"人間の言語習得に関してはまだまだ不明のことが多い。","japanese_furigana":"人間の言語習得に関してはまだまだ不明のことが多い。","english":"Concerning human language acquisition, there are still many unknown things."}]'::jsonb),
    ('dbdae833-0e7c-4512-8bdd-a198bdd7bac4'::uuid,ARRAY['Noun に限らず']::text[],ARRAY['Use this construction to express Not limiting something to ~.. Not limiting something to ~.']::text[],ARRAY['【Related Expression: だけで(は)なく~も】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"見合い結婚は日本に限らずほかの国でも行われている。","japanese_furigana":"見合い結婚は日本に限らずほかの国でも行われている。","english":"Arranged marriage is not limited to Japan; it is practiced in other countries, too."},{"japanese":"音楽はクラシックに限らず何でも聞きます。","japanese_furigana":"音楽はクラシックに限らず何でも聞きます。","english":"Talking about music, I listen to any music, not just classical music."}]'::jsonb),
    ('6c86a074-7b87-46f0-8175-0629bfc142d0'::uuid,ARRAY['Vnegative ぬ (Noun/Auxillary)']::text[],ARRAY['Use this construction to express An archaic auxiliary that indicates negation.. An archaic auxiliary that indicates negation.']::text[],ARRAY['【Related Expression: ない; ず】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"グローバルな時代に自国のことだけを考えるわけにはいかぬ。","japanese_furigana":"グローバルな時代に自国のことだけを考えるわけにはいかぬ。","english":"In the global age we cannot think of our own country alone."},{"japanese":"知らぬことを知らぬと言うには勇気が要る。","japanese_furigana":"知らぬことを知らぬと言うには勇気が要る。","english":"When you don''t know something, it takes courage to admit it."}]'::jsonb),
    ('c8026791-0a83-4e00-89a2-4d2f67686ba8'::uuid,ARRAY['Noun のこと']::text[],ARRAY['Use this construction to express Things of/about.. Things of/about.']::text[],ARRAY['【Related Expression: に関して/関する; について】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"私は明日の講義で日本文化のことを話すつもりだ。","japanese_furigana":"私は明日の講義で日本文化のことを話すつもりだ。","english":"I''m going to talk about Japanese culture in my lecture tomorrow."},{"japanese":"彼女のことはもう忘れた方がいいよ。","japanese_furigana":"彼女のことはもう忘れた方がいいよ。","english":"You''d better forget about her now."}]'::jsonb),
    ('b499034b-8c5b-400f-b5e4-5fdf56f09ea3'::uuid,ARRAY['Noun のことだから']::text[],ARRAY['Use this construction to express Because it is a matter of X with which/whom something is habitually the case.. Because it is a matter of X with which/whom something is habitually the case.']::text[],ARRAY['The core sense is Because it is a matter of X with which/whom something is habitually the case.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"中島のことだから、今日もまた遅れて来るだろう。","japanese_furigana":"中島のことだから、今日もまた遅れて来るだろう。","english":"Because Nakajima is always that way (i.e., comes late), he will probably come late again today. (literally: Because it is a matter of Nakajima (who habitually comes late))."},{"japanese":"傷みやすい豆腐のことだから、冷蔵庫に入れておいた方がいいですよ。","japanese_furigana":"傷みやすい豆腐のことだから、冷蔵庫に入れておいた方がいいですよ。","english":"Because tofu goes bad quickly, you''d better put it in the refrigerator. (literally: Because it is a matter of tofu, which always goes bad quickly . . .)"}]'::jsonb),
    ('b0976b98-eb8e-49ec-a11e-df7b65754c3c'::uuid,ARRAY['(i) {V/Adjective い} informal のだ']::text[],ARRAY['Use this construction to express A sentence ending which indicates that the speaker is explaining or asking for an explanation about some information shared with the hearer, or is talking about something emotively, as if it were of common interest to the speaker and the hearer.. A sentence ending which indicates that the speaker is explaining or asking for an explanation about some information shared with the hearer, or is talking about something emotively, as if it were of common interest to the speaker and the hearer.']::text[],ARRAY['The core sense is A sentence ending which indicates that the speaker is explaining or asking for an explanation about some information shared with the hearer, or is talking about something emotively, as if it were of common interest to the speaker and the hearer.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"何をしているん・のですか。","japanese_furigana":"何をしているん・のですか。","english":"What are you doing?"},{"japanese":"日本語を勉強しているん・のです。","japanese_furigana":"日本語を勉強しているん・のです。","english":"I''m studying Japanese."}]'::jsonb),
    ('4e834db5-eecc-4419-9ac3-4a40dddb1187'::uuid,ARRAY['Noun の上では']::text[],ARRAY['Use this construction to express As far as ~ is concerned.. As far as ~ is concerned.']::text[],ARRAY['【Related Expression: じょうは】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"この計画は書類の上では問題なさそうだ。","japanese_furigana":"この計画は書類の上では問題なさそうだ。","english":"There seems to be no problem with this plan as far as the documents are concerned."},{"japanese":"計算の上では二百万円ぐらい儲かることになっている。","japanese_furigana":"計算の上では二百万円ぐらい儲かることになっている。","english":"According to the calculations, we are supposed to make a profit of (about) two million yen."}]'::jsonb),
    ('a14c3a76-8d25-4297-9d36-4bec989a1204'::uuid,ARRAY['Noun の下で']::text[],ARRAY['Use this construction to express Under some object; under the control or influence of someone or something.. Under some object; under the control or influence of someone or something.']::text[],ARRAY['【Related Expression: かで】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"私は鈴木先生の指導の下で修士論文を書き上げた。","japanese_furigana":"私は鈴木先生の指導の下で修士論文を書き上げた。","english":"I finished my master''s thesis under Professor Suzuki''s guidance."},{"japanese":"さんさんたる太陽の下で開会式が行われた。","japanese_furigana":"さんさんたる太陽の下で開会式が行われた。","english":"The opening ceremony was held in (literally: under) the brilliant sun."}]'::jsonb),
    ('0f4f4545-e19a-4033-b2ce-3ebd4d1376d7'::uuid,ARRAY['Canonical pattern: は〜が']::text[],ARRAY['Use this construction to express A construction which relates a non-controllable state of something or someone to a topic. A construction which relates a non-controllable state of something or someone to a topic']::text[],ARRAY['The core sense is A construction which relates a non-controllable state of something or someone to a topic; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"私は英語が分かる・分かります。","japanese_furigana":"私は英語が分かる・分かります。","english":"To me, English is understandable."},{"japanese":"花子は目が奇麗だ・奇麗です。","japanese_furigana":"花子は目が奇麗だ・奇麗です。","english":"Speaking of Hanako, her eyes are pretty."}]'::jsonb),
    ('852084c3-01b2-43da-b941-ad9a915d6c23'::uuid,ARRAY['Canonical pattern: は〜だ']::text[],ARRAY['Use this construction to express Someone or something is/was someone or something or is/was in some state, or will do/does/did something.. Someone or something is/was someone or something or is/was in some state, or will do/does/did something.']::text[],ARRAY['The core sense is Someone or something is/was someone or something or is/was in some state, or will do/does/did something.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"これは本だ・です。","japanese_furigana":"これは本だ・です。","english":"This is a book."},{"japanese":"コンサートは八時からだ・です。","japanese_furigana":"コンサートは八時からだ・です。","english":"The concert is from eight o''clock."}]'::jsonb),
    ('73ad8ee4-166e-4718-9a37-cdaa6575f399'::uuid,ARRAY['(i) Vinformal past ばかりに']::text[],ARRAY['Use this construction to express A conjunction indicating that a single factor causes a negative situation.. A conjunction indicating that a single factor causes a negative situation.']::text[],ARRAY['The core sense is A conjunction indicating that a single factor causes a negative situation.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"僕が一言変なことを言ったばかりに彼女との関係は悪くなってしまった。","japanese_furigana":"僕が一言変なことを言ったばかりに彼女との関係は悪くなってしまった。","english":"Just because I said one nasty thing to her, my relationship with her deteriorated."},{"japanese":"あの子は、体が弱いばかりにクラスメートにいじめられている。","japanese_furigana":"あの子は、体が弱いばかりにクラスメートにいじめられている。","english":"That child is being bullied by his classmates simply because he is (physically) weak."}]'::jsonb),
    ('769dbdb0-7982-4140-81be-a117f3646f58'::uuid,ARRAY['(i) {v/Adjective い} Conditional ばこそ']::text[],ARRAY['Use this construction to express A conjunction that emphasizes a reason. A conjunction that emphasizes a reason']::text[],ARRAY['【Related Expression: からこそ】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"環境保護を支持していればこそ植林に力を入れているのだ。","japanese_furigana":"環境保護を支持していればこそ植林に力を入れているのだ。","english":"It is only because I support environmental protection so much that I put my efforts into planting trees."},{"japanese":"「愛」があればこそ生きる喜びがある。","japanese_furigana":"「愛」があればこそ生きる喜びがある。","english":"Only because there is love is there joy for living."}]'::jsonb),
    ('e62ad074-7b57-4869-9abe-5b6bb15c6853'::uuid,ARRAY['(i) はたして {V/Adjectiveい}informal past']::text[],ARRAY['Use this construction to express An adverb indicating that something occurred as the writer expected, or expressing in a concession clause the writer’s strong doubt.. An adverb indicating that something occurred as the writer expected, or expressing in a concession clause the writer’s strong doubt.']::text[],ARRAY['【Related Expression: やはり/やっぱり; 案の定】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"今年の冬も暖冬だと言われていたが、はたして暖冬だった。","japanese_furigana":"今年の冬も暖冬だと言われていたが、はたして暖冬だった。","english":"They said this would be a warm winter, and indeed it has been."},{"japanese":"はたして日本の教育は改革される(の)だろうか。","japanese_furigana":"はたして日本の教育は改革される(の)だろうか。","english":"I wonder if Japanese education will really be reformed at all."}]'::jsonb),
    ('5dc27c39-1f6d-4ff8-955d-40282435cb27'::uuid,ARRAY['Noun は言うまでもなく']::text[],ARRAY['Use this construction to express An adverbial phrase that conveys the meaning of ''not to speak of something/someone''.. An adverbial phrase that conveys the meaning of ''not to speak of something/someone''.']::text[],ARRAY['【Related Expression: ばかりで(は)なく~(も); は言うに及ばず; はもちろん】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"大統領の職務は頭脳は言うまでもなく、体力も要求される。","japanese_furigana":"大統領の職務は頭脳は言うまでもなく、体力も要求される。","english":"The duty of the presidency requires physical strength, not to mention brains."},{"japanese":"日本は土地は言うまでもなく、家も非常に高い。","japanese_furigana":"日本は土地は言うまでもなく、家も非常に高い。","english":"In Japan houses are very expensive, not to mention land."}]'::jsonb),
    ('a2107509-c544-448f-aa2e-ed6a77499aaf'::uuid,ARRAY['(i) ~ Vます ひいては Sentence。']::text[],ARRAY['Use this construction to express An adverb indicating that something is perceived to eventually lead to a signiﬁcant result.. An adverb indicating that something is perceived to eventually lead to a signiﬁcant result.']::text[],ARRAY['【Related Expression: 更に(は)】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"イラクへの攻撃はアメリカの孤立を招き、ひいてはイスラム社会全体との戦争に発展していく恐れがある。","japanese_furigana":"イラクへの攻撃はアメリカの孤立を招き、ひいてはイスラム社会全体との戦争に発展していく恐れがある。","english":"There is fear that an attack against Iraq will bring about American isolation, and eventually will lead to a war with Muslim society as a whole."},{"japanese":"彼は同僚にライバル意識、ひいては殺意すら抱いていた。","japanese_furigana":"彼は同僚にライバル意識、ひいては殺意すら抱いていた。","english":"He regarded his colleague as a rival, even to the point of considering murder."}]'::jsonb),
    ('263994a3-4fee-45be-82f7-421f2852f0bf'::uuid,ARRAY['(i) ひとつ Vてみよう。']::text[],ARRAY['Use this construction to express An adverb used when the speaker intends to do something, or asks someone a favour, or makes a suggestion or gives advice to someone.. An adverb used when the speaker intends to do something, or asks someone a favour, or makes a suggestion or gives advice to someone.']::text[],ARRAY['The core sense is An adverb used when the speaker intends to do something, or asks someone a favour, or makes a suggestion or gives advice to someone.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"ひとつ日本の小説の英訳をやってみょう。","japanese_furigana":"ひとつ日本の小説の英訳をやってみょう。","english":"I will try to translate a Japanese novel into English."},{"japanese":"ひとつゴルフでもやったらどうですか。","japanese_furigana":"ひとつゴルフでもやったらどうですか。","english":"How about giving golf a try?"}]'::jsonb),
    ('1ad30c53-54db-422b-9664-1f149ac5c21a'::uuid,ARRAY['Vinformal nonpast べく Exception: する→{す/する}べく']::text[],ARRAY['Use this construction to express The verb modification form of the auxiliary bekida, which is used to indicate a purpose or aim.. The verb modification form of the auxiliary bekida, which is used to indicate a purpose or aim.']::text[],ARRAY['【Related Expression: 為(に)】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"この大学では、二学期制に変えるべく今準備が進められている。","japanese_furigana":"この大学では、二学期制に変えるべく今準備が進められている。","english":"At this university, preparation is under way for changing (the current system) to a semester system."},{"japanese":"K社は人件費を削減すべく大規模なリストラを行う予定だ。","japanese_furigana":"K社は人件費を削減すべく大規模なリストラを行う予定だ。","english":"K Company plans to execute large-scale restructuring in order to reduce personnel expenses."}]'::jsonb),
    ('a9b01de3-effa-4d03-89e1-ff2263794b66'::uuid,ARRAY['(i) Noun のほうが Noun より']::text[],ARRAY['Use this construction to express Comparing two entities, one is in some state or does something more than the other.. Comparing two entities, one is in some state or does something more than the other.']::text[],ARRAY['【Related Expression: より】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"石田さんのほうが私より若い・若いです。","japanese_furigana":"石田さんのほうが私より若い・若いです。","english":"Mr. Ishida is younger than I am."},{"japanese":"私のほうが上田さんよりよく食べる・食べます。","japanese_furigana":"私のほうが上田さんよりよく食べる・食べます。","english":"I eat more than Ms. Ueda does."}]'::jsonb),
    ('8a3a6a86-2ec1-4e14-80c5-0cea148cd1a2'::uuid,ARRAY['Vinformal past ほうがいい']::text[],ARRAY['Use this construction to express It is strongly suggested that someone do something.. It is strongly suggested that someone do something.']::text[],ARRAY['【Related Expression: たらどうですか】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"日本語の本を読んだほうがいい・いいです。","japanese_furigana":"日本語の本を読んだほうがいい・いいです。","english":"You''d better read Japanese books."},{"japanese":"野菜も食べたほうがいいよ。","japanese_furigana":"野菜も食べたほうがいいよ。","english":"You''d better eat vegetables, too."}]'::jsonb),
    ('03c628ac-a595-4bcf-af02-61bffb1af0c2'::uuid,ARRAY['(i) まさか Sとは {思わなかった/考えてもみなかった}']::text[],ARRAY['Use this construction to express An adverb that indicates the speaker''s strong belief that something is not expected to (have) become a reality.. An adverb that indicates the speaker''s strong belief that something is not expected to (have) become a reality.']::text[],ARRAY['【Related Expression: よもや】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"まさか美智子があんな男と結婚するとは思わなかった。","japanese_furigana":"まさか美智子があんな男と結婚するとは思わなかった。","english":"I never dreamed that Michiko would marry that kind of a guy."},{"japanese":"まさかあたしの誕生日を忘れたんじゃないでしょうね。","japanese_furigana":"まさかあたしの誕生日を忘れたんじゃないでしょうね。","english":"Don''t tell me that you forgot my birthday!"}]'::jsonb),
    ('77a2fab9-387a-4b68-870d-59b095b09c47'::uuid,ARRAY['(i) Subordinate Clause、 まして ( や ) Main Clause。']::text[],ARRAY['Use this construction to express An adverb expressing the idea that because one statement is true, the subsequent statement is naturally true.. An adverb expressing the idea that because one statement is true, the subsequent statement is naturally true.']::text[],ARRAY['【Related Expression: どころか; いわんや】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"アパートの家賃を払うのが精一杯なのに、まして（や）家を買うなんて夢物語だ。","japanese_furigana":"アパートの家賃を払うのが精一杯なのに、まして（や）家を買うなんて夢物語だ。","english":"I am just managing to pay the rent for my apartment; how much more of a dream it is to imagine buying my own house!"},{"japanese":"彼女は日本語で講演もできる。まして（や）日常会話など問題ではない。","japanese_furigana":"彼女は日本語で講演もできる。まして（や）日常会話など問題ではない。","english":"She can give a speech in Japanese, to say nothing of (her ability to handle) everyday conversation."}]'::jsonb),
    ('00f87d5f-f746-4e89-9431-d69d92b32574'::uuid,ARRAY['Vます ましょう']::text[],ARRAY['Use this construction to express A verb ending which indicates the first person’s volition or invitation in formal speech.. A verb ending which indicates the first person’s volition or invitation in formal speech.']::text[],ARRAY['【Related Expression: ませんか】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"私が彼に話しましょう。","japanese_furigana":"私が彼に話しましょう。","english":"I will talk to him."},{"japanese":"映画に行きましょう。","japanese_furigana":"映画に行きましょう。","english":"Let''s go to a movie."}]'::jsonb),
    ('8f4dba6e-924a-46fc-81d7-1fb9947b1d07'::uuid,ARRAY['(i) また Verb [repetition]']::text[],ARRAY['Use this construction to express An adverb/conjunction that indicates repetition or addition.. An adverb/conjunction that indicates repetition or addition.']::text[],ARRAY['【Related Expression: あるいは; 且つ】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"来年の春、またお会いします。","japanese_furigana":"来年の春、またお会いします。","english":"I will see you again next spring."},{"japanese":"山田も東京出身だが、林もまた東京出身だ。","japanese_furigana":"山田も東京出身だが、林もまた東京出身だ。","english":"Yamada is from Tokyo, and Hayashi, too, is from Tokyo."}]'::jsonb),
    ('17c9135c-e8a7-4e97-8683-a6c0f94adf9e'::uuid,ARRAY['(i) Noun (か)、 または Noun']::text[],ARRAY['Use this construction to express A conjunction which connects two choices or possibilities expressed by noun phrases or sentences.. A conjunction which connects two choices or possibilities expressed by noun phrases or sentences.']::text[],ARRAY['【Related Expression: か~; か~かどちらか; それとも】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"現金（か）、または小切手でお払い下さい。","japanese_furigana":"現金（か）、または小切手でお払い下さい。","english":"Please pay either in cash or by check."},{"japanese":"Ａ（か）、またはＢのどちらかを選びなさい。","japanese_furigana":"Ａ（か）、またはＢのどちらかを選びなさい。","english":"Select either A or B."}]'::jsonb),
    ('92053bb2-b873-4530-addf-4c7cd78f4cfd'::uuid,ARRAY['Vinformal nonpast までもない']::text[],ARRAY['Use this construction to express There is no point in going as far as to do something.. There is no point in going as far as to do something.']::text[],ARRAY['【Related Expression: 必要はない; ほどのこともない; には及ばない】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"これは簡単な計算だから計算器を使うまでもない。","japanese_furigana":"これは簡単な計算だから計算器を使うまでもない。","english":"This is a simple calculation, so it is not necessary (to bother) to use a calculator."},{"japanese":"言うまでもなくジョージ・ワシントンはアメリカの初代大統領だ。","japanese_furigana":"言うまでもなくジョージ・ワシントンはアメリカの初代大統領だ。","english":"Needless to say, George Washington was the first president of the United States."}]'::jsonb),
    ('d4665971-bb82-46ae-9893-65282cd36cc7'::uuid,ARRAY['(i) Vinformal past まま']::text[],ARRAY['Use this construction to express An already given situation or condition remains unaltered.. An already given situation or condition remains unaltered.']::text[],ARRAY['【Related Expression: ないで; ずに】】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"弟はテレビをつけたまま寝てしまった・しまいました。","japanese_furigana":"弟はテレビをつけたまま寝てしまった・しまいました。","english":"My younger brother went to sleep leaving the TV on."},{"japanese":"弟はテレビをつけたままにしておいた・おきました。","japanese_furigana":"弟はテレビをつけたままにしておいた・おきました。","english":"My younger brother left the TV on."}]'::jsonb),
    ('a4c3d9c4-eb9e-4988-8ed5-0658148e4e64'::uuid,ARRAY['Vて みせる (Group 2)']::text[],ARRAY['Use this construction to express The speaker''s strong determination to achieve something for others to see.. The speaker''s strong determination to achieve something for others to see.']::text[],ARRAY['The core sense is The speaker''s strong determination to achieve something for others to see.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"僕は小説を書いて、芥川賞を取ってみせる。","japanese_furigana":"僕は小説を書いて、芥川賞を取ってみせる。","english":"I will definitely write a novel and get the Akutagawa Prize."},{"japanese":"僕はこの会社の社長になってみせる。","japanese_furigana":"僕はこの会社の社長になってみせる。","english":"I am determined to become the president of this company."}]'::jsonb),
    ('6e03262c-071d-4f22-8c53-d8cbf09a5496'::uuid,ARRAY['Vて みる']::text[],ARRAY['Use this construction to express Do something to see what it’s like or what will happen.. Do something to see what it’s like or what will happen.']::text[],ARRAY['【Related Expression: ようとする】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"私は日本の小説を読んでみる・みます。","japanese_furigana":"私は日本の小説を読んでみる・みます。","english":"I will read Japanese novels (to see what they are like)."},{"japanese":"面白そうなコンサートだったので行ってみました。","japanese_furigana":"面白そうなコンサートだったので行ってみました。","english":"Since it seemed interesting, I went to the concert (to see what it was like)."}]'::jsonb),
    ('0319512e-2caf-4f68-8411-ff61e7e9dba7'::uuid,ARRAY['(i) V1informal nonpastより({は/も}) むしろ V2informal nonpast (方が～)']::text[],ARRAY['Use this construction to express An adverb that indicates one of two things/people/characteristics has been chosen rather than the other to express speaker’s/writer’s desire, preference or judgment.. An adverb that indicates one of two things/people/characteristics has been chosen rather than the other to express speaker’s/writer’s desire, preference or judgment.']::text[],ARRAY['【Related Expression: かえって; どちらかと言うと】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"夏休みはアルバイトをするよりもむしろ海外旅行がしたい。","japanese_furigana":"夏休みはアルバイトをするよりもむしろ海外旅行がしたい。","english":"During summer vacation I would rather travel abroad than work part-time."},{"japanese":"僕は寿司よりむしろ刺身(の方）が好きだ。","japanese_furigana":"僕は寿司よりむしろ刺身(の方）が好きだ。","english":"I prefer sashimi rather than sushi."}]'::jsonb),
    ('35727416-7d3b-4488-9ddc-8f9f7f95fb3e'::uuid,ARRAY['(i) Noun 1 (か)、 もしくは Noun 2']::text[],ARRAY['Use this construction to express A conjunction to disjunctively connect two items or ideas.. A conjunction to disjunctively connect two items or ideas.']::text[],ARRAY['【Related Expression: それとも; あるいは; まただ; か; ないし(は)】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"この申込書は本人（か）、もしくは保証人が記入しなければならない。","japanese_furigana":"この申込書は本人（か）、もしくは保証人が記入しなければならない。","english":"This application has to be filled in by the applicant or by his/her guarantor."},{"japanese":"ワークショップに出席なさりたい方はオンラインで登録するか、もしくは、メールでお申し込みください。","japanese_furigana":"ワークショップに出席なさりたい方はオンラインで登録するか、もしくは、メールでお申し込みください。","english":"If you want to participate in the workshop, please register online or apply by e-mail."}]'::jsonb),
    ('5f2f1549-c262-4ecc-a211-85fa2e6f4847'::uuid,ARRAY['Sentence1。 もっとも Sentence2({が/けれども})。']::text[],ARRAY['Use this construction to express A conjunction used to add a comment indicating that what the speaker/writer has just expressed is not sufﬁcient.. A conjunction used to add a comment indicating that what the speaker/writer has just expressed is not sufﬁcient.']::text[],ARRAY['【Related Expression: しかし; とは言うものの; ただ】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"運動は体にいいと言われている。もっとも、やりすぎると逆効果だ（が）。","japanese_furigana":"運動は体にいいと言われている。もっとも、やりすぎると逆効果だ（が）。","english":"They say that exercise is good for you (literally: your body), but doing too much will bring about the opposite effect."},{"japanese":"あの政治家は保守的だと言われている。もっとも、時々革新的なことを言うこともあるが。","japanese_furigana":"あの政治家は保守的だと言われている。もっとも、時々革新的なことを言うこともあるが。","english":"That politician is said to be conservative, although he sometimes makes innovative statements."}]'::jsonb),
    ('0d93378e-82d9-4b8a-b2d7-96c382801dda'::uuid,ARRAY['(i) Vinformal nonpast ものではない']::text[],ARRAY['Use this construction to express A sentence-ﬁnal phrase indicating that one shouldn’t do something, one could not possibly do something, or one naturally cannot do something.. A sentence-ﬁnal phrase indicating that one shouldn’t do something, one could not possibly do something, or one naturally cannot do something.']::text[],ARRAY['【Related Expression: べきではない; てはいけない; 当然だ; 当たり前だ】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"夜遅く人に電話をかけるものではない。","japanese_furigana":"夜遅く人に電話をかけるものではない。","english":"You shouldn''t call people late at night."},{"japanese":"彼の演奏は聴けたものではない。","japanese_furigana":"彼の演奏は聴けたものではない。","english":"We cannot bear listening to his performance (literally: His performance isn''t something we could possibly listen to)."}]'::jsonb),
    ('47f0483a-66aa-4c0b-98b6-1bdc48433c59'::uuid,ARRAY['Vpotential informal nonpast ものなら']::text[],ARRAY['Use this construction to express A conjunction indicating that the preceding clause presents a hypothetical situation that is unlikely to become a reality.. A conjunction indicating that the preceding clause presents a hypothetical situation that is unlikely to become a reality.']::text[],ARRAY['The core sense is A conjunction indicating that the preceding clause presents a hypothetical situation that is unlikely to become a reality.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"（もし）一戸建ての家が買えるものなら買いたい。","japanese_furigana":"（もし）一戸建ての家が買えるものなら買いたい。","english":"If I could buy a single family house, I would like to."},{"japanese":"一人でやれるものならやってみろ！","japanese_furigana":"一人でやれるものならやってみろ！","english":"If (you think) you can do it by yourself, go ahead and do it!"}]'::jsonb),
    ('8a515e62-ae6f-4a7a-bc0b-49d6d345a6fa'::uuid,ARRAY['(i) {V/Adjectiveい}informal ものの']::text[],ARRAY['Use this construction to express A conjunction that means “although”.. A conjunction that means “although”.']::text[],ARRAY['【Related Expression: が; けれども】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"通訳の仕事を引き受けたものの、うまくやれる自信がない。","japanese_furigana":"通訳の仕事を引き受けたものの、うまくやれる自信がない。","english":"Although I accepted the interpreting job, I''m not conﬁdent that I can do it well."},{"japanese":"一人でいる方が気楽だとは言うものの、やはり話し相手が欲しいと思うこともある。","japanese_furigana":"一人でいる方が気楽だとは言うものの、やはり話し相手が欲しいと思うこともある。","english":"Although I say being alone is easier, sometimes I want someone to talk with."}]'::jsonb),
    ('cb2e65c0-ddbd-4c7b-9b0b-b8c427d711c2'::uuid,ARRAY['(i) Vconditionalば{Adjectiveい/Vpotential}informal ものを']::text[],ARRAY['Use this construction to express A disjunctive coordinate conjunction expressing the meaning of “although” with the speaker’s strong feeling of discontent. A disjunctive coordinate conjunction expressing the meaning of “although” with the speaker’s strong feeling of discontent']::text[],ARRAY['【Related Expression: のに】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"彼は日本語を続けて勉強すればいいものを、1年間やっただけでやめてしまった。","japanese_furigana":"彼は日本語を続けて勉強すればいいものを、1年間やっただけでやめてしまった。","english":"Although he should have continued studying Japanese, he quit after only one year."},{"japanese":"すぐ医者に診てもらったら簡単に治っていたものを、手遅れになってしまった。","japanese_furigana":"すぐ医者に診てもらったら簡単に治っていたものを、手遅れになってしまった。","english":"Had I gone to the doctor right away, I would have gotten better easily, but I acted too late."}]'::jsonb),
    ('04e44d38-47d6-4de8-a64a-e5f90345fb07'::uuid,ARRAY['Canonical pattern: や']::text[],ARRAY['Use this construction to express A coordinate conjunction that is used to list two or more items (nouns or noun phrases) in an inexhaustive fashion.. A coordinate conjunction that is used to list two or more items (nouns or noun phrases) in an inexhaustive fashion.']::text[],ARRAY['【Related Expression: と1; とか】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"山田さんや小川さんが来た・来ました。","japanese_furigana":"山田さんや小川さんが来た・来ました。","english":"Mr. Yamada and Mr. Ogawa (and others) came."},{"japanese":"山本さんやスミスさんがテニスをしている。","japanese_furigana":"山本さんやスミスさんがテニスをしている。","english":"Mr. Yamamoto, Mr. Smith and others are playing tennis."}]'::jsonb),
    ('267f673b-575a-4b34-b1b0-6ebc132f9088'::uuid,ARRAY['(i) やっと Vinformal']::text[],ARRAY['Use this construction to express An adverb to indicate that something desirable has been finally achieved or will be eventually achieved though with great difficulty.. An adverb to indicate that something desirable has been finally achieved or will be eventually achieved though with great difficulty.']::text[],ARRAY['【Related Expression: かろうじて; なんとか; とうとう; ようやく】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"日本史の期末レポートやっと書き終えた。","japanese_furigana":"日本史の期末レポートやっと書き終えた。","english":"I finally finished writing my Japanese history term paper."},{"japanese":"この道は車がやっと一台通れるくらいの狭さです。","japanese_furigana":"この道は車がやっと一台通れるくらいの狭さです。","english":"This street is so narrow that one car can barely go through."}]'::jsonb),
    ('6ab65ca3-a274-4d02-9530-c69a2bd17d2a'::uuid,ARRAY['Canonical pattern: やはり']::text[],ARRAY['Use this construction to express An adverb indicating that the actual situation expectedly/anticipatively conforms to a standard based on past experience, comparison with other people, or common sense.. An adverb indicating that the actual situation expectedly/anticipatively conforms to a standard based on past experience, comparison with other people, or common sense.']::text[],ARRAY['【Related Expression: 結局; さすが(に)】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"ベイリーさんはやはり来なかった・来ませんでしたね。","japanese_furigana":"ベイリーさんはやはり来なかった・来ませんでしたね。","english":"As expected, Mr. Bailey hasn''t come, has he?"},{"japanese":"雪子さんは今でもやはり奇麗です。","japanese_furigana":"雪子さんは今でもやはり奇麗です。","english":"Yukiko is still pretty."}]'::jsonb),
    ('012b2c17-3794-4047-9481-c8b0437b2458'::uuid,ARRAY['(i) Sinformalの やら だ after Adjectiveなstem and Noun changes to な']::text[],ARRAY['Use this construction to express A sentence-ﬁnal particle that marks a self-addressed question.. A sentence-ﬁnal particle that marks a self-addressed question.']::text[],ARRAY['【Related Expression: だろうか; かしら; か】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"このビルが完成するのはいつになるのやら。","japanese_furigana":"このビルが完成するのはいつになるのやら。","english":"I wonder when this building will be ﬁnished."},{"japanese":"これから先、うちの会社は一体どうなることやら。","japanese_furigana":"これから先、うちの会社は一体どうなることやら。","english":"I wonder what will happen to our company from now on. (I''m quite worried.)"}]'::jsonb),
    ('33e5192e-dd91-478e-ab05-5359d4084040'::uuid,ARRAY['(i) someone が someone を place にやる']::text[],ARRAY['Use this construction to express To cause something/someone to move to a place or to do/eat/drink something.. To cause something/someone to move to a place or to do/eat/drink something.']::text[],ARRAY['【Related Expression: する】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"貧乏な家庭は子共を大学にやれない。","japanese_furigana":"貧乏な家庭は子共を大学にやれない。","english":"Poor families cannot send their children to college."},{"japanese":"僕は弟に自転車をやるつもりだ。","japanese_furigana":"僕は弟に自転車をやるつもりだ。","english":"I intend to give a bike to my younger brother."}]'::jsonb),
    ('6a3bf580-5f8f-4510-b8b5-a1ba93c965bf'::uuid,ARRAY['Vinformal nonpast や否や']::text[],ARRAY['Use this construction to express A conjunction that expresses the idea that something happened or someone did something immediately following another event or action.. A conjunction that expresses the idea that something happened or someone did something immediately following another event or action.']::text[],ARRAY['【Related Expression: や; 途端(に); と同時に; とすぐ(に); たらすぐ(に); なり; が早いか; 瞬間に】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"その小説は発売されるや否やミリオンセラーになった。","japanese_furigana":"その小説は発売されるや否やミリオンセラーになった。","english":"The novel sold one million copies as soon as it went on sale."},{"japanese":"彼女は車から降りるや否や報道陣やファンに取り囲まれた。","japanese_furigana":"彼女は車から降りるや否や報道陣やファンに取り囲まれた。","english":"She was surrounded by reporters and fans as soon as she got out of the car."}]'::jsonb),
    ('5daf2e6d-187d-4280-a975-6767816884f0'::uuid,ARRAY['(i) {V/Adjectiveい}informal nonpast ようでは']::text[],ARRAY['Use this construction to express A conjunction that presents an undesirable situation, which is assumed to be factual.. A conjunction that presents an undesirable situation, which is assumed to be factual.']::text[],ARRAY['【Related Expression: ては】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"知らない単語が出てくるたびに辞書を引いているようではいつまでたっても速く読めない。","japanese_furigana":"知らない単語が出てくるたびに辞書を引いているようではいつまでたっても速く読めない。","english":"If (it is true that) you look up unfamiliar words in the dictionary every time you encounter a new one, you will never learn to read fast."},{"japanese":"アパートがそんなに高いようでは私たちは東京には住めない。","japanese_furigana":"アパートがそんなに高いようでは私たちは東京には住めない。","english":"If (it is true that) apartments in Tokyo are that expensive, we cannot live there."}]'::jsonb),
    ('dfeb04ec-66ec-4b6f-8f16-311fa392f605'::uuid,ARRAY['Vinformal nonpast ように言う']::text[],ARRAY['Use this construction to express Tell someone in such a way that he will do something.. Tell someone in such a way that he will do something.']::text[],ARRAY['The core sense is Tell someone in such a way that he will do something.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"先生は学生に宿題をするように言った・言いました。","japanese_furigana":"先生は学生に宿題をするように言った・言いました。","english":"The teacher told his students to do homework."},{"japanese":"坂本さんは雪江に図書館の前で待っているように言いった。","japanese_furigana":"坂本さんは雪江に図書館の前で待っているように言いった。","english":"Mr. Sakamoto told Yukie to be waiting in front of the library."}]'::jsonb),
    ('d32b7721-945d-412e-a36a-9d985f9eb9fb'::uuid,ARRAY['(i) Vnegative んばかりに Exception: する→せんばかりに']::text[],ARRAY['Use this construction to express An adverbial phrase that is used when a situation looks as if someone were about to do something or as if something were about to occur literally or ﬁguratively.. An adverbial phrase that is used when a situation looks as if someone were about to do something or as if something were about to occur literally or ﬁguratively.']::text[],ARRAY['The core sense is An adverbial phrase that is used when a situation looks as if someone were about to do something or as if something were about to occur literally or ﬁguratively.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"犬は噛みつかんばかりに僕に向かってほえた。","japanese_furigana":"犬は噛みつかんばかりに僕に向かってほえた。","english":"The dog barked at me as if it were about to bite."},{"japanese":"どの演奏も若さと情熱あふれんばかりに満ちていた。","japanese_furigana":"どの演奏も若さと情熱あふれんばかりに満ちていた。","english":"Every performance was ﬁlled with an overwhelming amount of youth and passion (literally: as if youth and passion were about to overﬂow)."}]'::jsonb),
    ('ddfc6efa-89e7-4d05-94d4-1de7d259dfca'::uuid,ARRAY['(i) 一つには (もう) 一つには ～']::text[],ARRAY['Use this construction to express An adverb meaning “partly” in a context where someone gives one or two objectives, benefits, examples or reasons for something.. An adverb meaning “partly” in a context where someone gives one or two objectives, benefits, examples or reasons for something.']::text[],ARRAY['The core sense is An adverb meaning “partly” in a context where someone gives one or two objectives, benefits, examples or reasons for something.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"大学教育の目的は、一つには幅広い教養と専門的な知識・能力を授けること、一つには社会に貢献する指導者を育成することだ。","japanese_furigana":"大学教育の目的は、一つには幅広い教養と専門的な知識・能力を授けること、一つには社会に貢献する指導者を育成することだ。","english":"The objective of college education is partly to provide broad schooling and professional knowledge and ability, and partly to train and produce leaders who will contribute to society."},{"japanese":"彼が外国語を好んで勉強しているのは、一つには、異文化学習が好きだからだ。","japanese_furigana":"彼が外国語を好んで勉強しているのは、一つには、異文化学習が好きだからだ。","english":"One reason he likes studying foreign languages is because he likes to learn about different cultures."}]'::jsonb),
    ('0c153a6e-b6e4-48d8-911b-bb3d6ef75fb1'::uuid,ARRAY['Canonical pattern: 一応']::text[],ARRAY['Use this construction to express An adverb indicating that an action or state is only temporary or tentative or is superﬁcially conceived.. An adverb indicating that an action or state is only temporary or tentative or is superﬁcially conceived.']::text[],ARRAY['【Related Expression: とりあえず】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"会議の日取りを一応来週の水曜日と決めておきましょう。","japanese_furigana":"会議の日取りを一応来週の水曜日と決めておきましょう。","english":"Let''s tentatively set our meeting date for next Wednesday."},{"japanese":"私は一応トムにその仕事を担当させることにした。","japanese_furigana":"私は一応トムにその仕事を担当させることにした。","english":"I''ve put Tom in charge of the project for the time being."}]'::jsonb),
    ('53b3aee8-d5e1-4f00-a4d1-97076db656f4'::uuid,ARRAY['(i) {V/Adjectiveい}informal 一方 ( で )']::text[],ARRAY['Use this construction to express A conjunction used to present two concurrent actions/events/states or contrastive situations.. A conjunction used to present two concurrent actions/events/states or contrastive situations.']::text[],ARRAY['【Related Expression: かたわら; 反面】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"我々は化石燃料による環境汚染の問題に対応する一方（で）、新しいエネルギーの開発に力を入れなければならない。","japanese_furigana":"我々は化石燃料による環境汚染の問題に対応する一方（で）、新しいエネルギーの開発に力を入れなければならない。","english":"We have to make more effort in developing new energy (sources) while countering the problem of environmental pollution caused by fossil fuels."},{"japanese":"企業はIT投資には熱心な一方（で）、セキュリティ意識はまだ低いところが多い。","japanese_furigana":"企業はIT投資には熱心な一方（で）、セキュリティ意識はまだ低いところが多い。","english":"Many companies are still not very conscious about (information) security, even though they are eager to invest in information technology."}]'::jsonb),
    ('0d8836af-a17f-4419-bbf1-9da638923333'::uuid,ARRAY['一旦 Verb']::text[],ARRAY['Use this construction to express An adverb meaning “once” or “for a short time”.. An adverb meaning “once” or “for a short time”.']::text[],ARRAY['【Related Expression: 一度】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"このは小説一旦読み始めたらやめられない。","japanese_furigana":"このは小説一旦読み始めたらやめられない。","english":"Once you begin reading this novel, you won''t be able to put it down (literally: stop reading it)."},{"japanese":"邦彦は一旦やめたタバコをまた吸い出した。","japanese_furigana":"邦彦は一旦やめたタバコをまた吸い出した。","english":"Kunihiko resumed smoking, which he had quit for a time."}]'::jsonb),
    ('07d73f12-c35f-460e-8889-f5fc149626be'::uuid,ARRAY['(i) 一番 Adjective い/な']::text[],ARRAY['Use this construction to express A superlative marker.. A superlative marker.']::text[],ARRAY['The core sense is A superlative marker.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"クラス(の中)で大川さんが一番頭がいい。","japanese_furigana":"クラス(の中)で大川さんが一番頭がいい。","english":"Mr. Okawa is the brightest in the class."},{"japanese":"A:この中でどの映画が一番面白いですか。 B:この日本の映画でしょう。","japanese_furigana":"A:この中でどの映画が一番面白いですか。 B:この日本の映画でしょう。","english":"A: Among these, which movie is the most interesting? B: This Japanese movie, I guess."}]'::jsonb),
    ('1c83ad75-e1b5-44b6-967c-380decdd5421'::uuid,ARRAY['Sentence 上 ( に ) The same as relative clause connection rules']::text[],ARRAY['Use this construction to express A conjunction which introduces an additional, emphatic statement.. A conjunction which introduces an additional, emphatic statement.']::text[],ARRAY['【Related Expression: ばかりで(は)なく~も; ばかりか~(さえ); だけで(は)なく~も; その上】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"この映画は話の筋が面白い上（に）配役がいい。","japanese_furigana":"この映画は話の筋が面白い上（に）配役がいい。","english":"Besides the fact that this movie has an interesting storyline, the cast is good."},{"japanese":"彼は仕事を見つけてくれた上（に）お金まで貸してくれた。","japanese_furigana":"彼は仕事を見つけてくれた上（に）お金まで貸してくれた。","english":"Not only did he find me a job, he even lent me some money."}]'::jsonb),
    ('427f8d15-5e5c-4ea6-9e06-d4978135576e'::uuid,ARRAY['(i) {Vます/Vて}、 且つ']::text[],ARRAY['Use this construction to express A conjunction meaning “and” that connects words, phrases and sentences.. A conjunction meaning “and” that connects words, phrases and sentences.']::text[],ARRAY['【Related Expression: と; や; また; その上; 更に; 加えて; そして】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"スミス氏は流暢な日本語を話し、且つ日本の歴史や文化にも明るい。","japanese_furigana":"スミス氏は流暢な日本語を話し、且つ日本の歴史や文化にも明るい。","english":"Mr. Smith is ﬂuent in Japanese and is also knowledgeable about Japanese history and culture."},{"japanese":"この本は、分かりやすく、且つ味わい深い言葉で書かれている。","japanese_furigana":"この本は、分かりやすく、且つ味わい深い言葉で書かれている。","english":"This book is written in language that is easy to understand but also profound."}]'::jsonb)
)
update public.japanese_grammar_guides g
set formation=case when coalesce(array_length(g.formation,1),0)=0 then e.formation_value else g.formation end,
    usage=case when coalesce(array_length(g.usage,1),0)=0 then e.usage_value else g.usage end,
    nuance=case when coalesce(array_length(g.nuance,1),0)=0 then e.nuance_value else g.nuance end,
    reference_examples=case when jsonb_typeof(coalesce(g.reference_examples,'[]'::jsonb))='array' and jsonb_array_length(coalesce(g.reference_examples,'[]'::jsonb))=0 then e.examples_value else g.reference_examples end,
    updated_at=now()
from enrichment e
where g.id=e.grammar_id and g.user_id=(select user_id from private.app_owner);

commit;
